head.b:skin:
/*
  Theme Name: Singh Creative Studio Premium Light Portfolio
  Founder: MUKESH SINGH
  Tagline: Ideas Made Visible.
*/
:root {
  --bg: #FFFFFF;
  --panel: #F5F8FF;
  --card: #FFFFFF;
  --primary: #4F46E5;
  --electric: #2563EB;
  --cyan: #06B6D4;
  --violet: #8B5CF6;
  --text: #111827;
  --muted: #64748B;
  --border: #E5EAF3;
  --glow: rgba(79, 70, 229, 0.14);
  --shadow-sm: 0 4px 12px rgba(17, 24, 39, 0.04);
  --shadow-md: 0 12px 28px rgba(79, 70, 229, 0.08);
  --shadow-lg: 0 20px 48px rgba(79, 70, 229, 0.12);
  --max: 1280px;
  --font-heading: 'Space Grotesk', sans-serif;
  --font-body: 'DM Sans', sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
  font-size: 16px;
  -webkit-tap-highlight-color: transparent;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  line-height: 1.6;
  overflow-x: hidden;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, select, textarea {
  font-family: inherit;
  font-size: inherit;
  background: none;
  border: none;
  color: inherit;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

svg {
  max-width: 100%;
}

.container {
  width: min(var(--max), calc(100% - 48px));
  margin-left: auto;
  margin-right: auto;
}

.display {
  font-family: var(--font-heading);
  letter-spacing: -0.05em;
}

.gradient-text {
  background: linear-gradient(135deg, #4F46E5 0%, #2563EB 50%, #06B6D4 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.eyebrow {
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.eyebrow::before {
  content: '';
  width: 24px;
  height: 2px;
  background: var(--primary);
  border-radius: 2px;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 18px;
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--primary);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  flex-shrink: 0;
}

/* Buttons & Interactive Elements */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 28px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: -0.01em;
  transition: all 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
  white-space: nowrap;
  border: 1px solid transparent;
}

.btn:hover {
  transform: translateY(-3px);
}

.btn-primary {
  background: linear-gradient(135deg, #4F46E5, #2563EB, #06B6D4);
  color: #FFFFFF;
  box-shadow: 0 8px 24px rgba(79, 70, 229, 0.25);
}

.btn-primary:hover {
  box-shadow: 0 12px 32px rgba(79, 70, 229, 0.4);
  color: #FFFFFF;
}

.btn-ghost {
  border-color: var(--primary);
  background: #FFFFFF;
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.btn-ghost:hover {
  background: rgba(79, 70, 229, 0.06);
  border-color: var(--electric);
  color: var(--electric);
}

/* Circular Icon Buttons */
.btn-icon {
  width: 46px;
  height: 46px;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: #FFFFFF;
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
  flex-shrink: 0;
}

.btn-icon svg {
  width: 20px;
  height: 20px;
  display: block;
}

.btn-icon svg line,
.btn-icon svg path,
.btn-icon svg circle,
.btn-icon svg rect,
.btn-icon svg polygon,
.btn-icon svg polyline {
  fill: none;
  stroke: #111827 !important;
  stroke-width: 2.2px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.btn-icon.active svg line,
.btn-icon.active svg path,
.btn-icon.active svg circle,
.btn-icon.active svg rect,
.btn-icon.active svg polygon,
.btn-icon.active svg polyline {
  stroke: #FFFFFF !important;
}

.btn-icon:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(79, 70, 229, 0.05);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-icon.active {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  color: #FFFFFF;
  border-color: transparent;
}

/* Topline Accent Bar */
.topline {
  height: 3px;
  background: linear-gradient(90deg, var(--primary), var(--cyan), var(--violet));
  position: relative;
  z-index: 1000;
}

/* Light Intro Screen with Cinematic Transition */
.intro {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  padding: 24px;
  background: radial-gradient(ellipse at 50% 35%, rgba(79, 70, 229, 0.12), transparent 60%), #FFFFFF;
  transition: opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1), transform 0.8s cubic-bezier(0.22, 1, 0.36, 1), visibility 0.8s;
  overflow: hidden;
}

.intro-glow-bg {
  position: absolute;
  inset: -50%;
  background: radial-gradient(circle at 50% 50%, rgba(79, 70, 229, 0.35), rgba(37, 99, 235, 0.2), rgba(6, 182, 212, 0.15), transparent 70%);
  opacity: 0;
  transform: scale(0.3);
  transition: transform 1.1s cubic-bezier(0.22, 1, 0.36, 1), opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
  z-index: 1;
}

.intro.transitioning .intro-glow-bg {
  opacity: 1;
  transform: scale(1.8);
}

.intro.hidden {
  opacity: 0;
  transform: scale(1.04);
  visibility: hidden;
  pointer-events: none;
}

.intro-inner {
  text-align: center;
  max-width: 680px;
  position: relative;
  z-index: 2;
  transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.intro.transitioning .intro-inner {
  transform: scale(1.06) translateY(-12px);
  opacity: 0;
}

#enterStudio {
  position: relative;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.3s cubic-bezier(0.22, 1, 0.36, 1), background 0.3s ease;
}

#enterStudio.active-cta {
  transform: scale(0.95);
  box-shadow: 0 0 35px rgba(79, 70, 229, 0.6), 0 0 60px rgba(6, 182, 212, 0.4);
}

body.intro-dismissed .header,
body.intro-dismissed .hero-copy,
body.intro-dismissed .visual-wrap {
  animation: heroEntrance 1.1s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes heroEntrance {
  0% {
    opacity: 0;
    transform: translateY(20px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.logo-monogram {
  width: 80px;
  height: 80px;
  border-radius: 24px;
  margin: 0 auto 24px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--primary) 0%, var(--electric) 50%, var(--cyan) 100%);
  color: #FFFFFF;
  font: 800 2.6rem var(--font-heading);
  box-shadow: 0 12px 36px rgba(79, 70, 229, 0.3);
  transform: rotate(-6deg);
  transition: transform 0.4s ease;
}

.logo-monogram:hover {
  transform: rotate(0deg) scale(1.05);
}

.logo-monogram span {
  transform: rotate(6deg);
  display: block;
}

.intro h1 {
  font: 800 clamp(2.4rem, 7.5vw, 4.8rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 0;
  color: var(--text);
}

.intro .founder {
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.35em;
  color: var(--primary);
  margin: 18px 0 6px;
  text-transform: uppercase;
}

.intro .tagline {
  color: var(--muted);
  font-size: 1.1rem;
  margin: 0 0 32px;
}

.intro-orbit {
  position: absolute;
  width: min(85vw, 650px);
  height: min(85vw, 650px);
  border: 1px solid rgba(79, 70, 229, 0.12);
  border-radius: 50%;
  pointer-events: none;
  z-index: 1;
}

.intro-orbit::after {
  content: '';
  position: absolute;
  inset: 12%;
  border: 1px dashed rgba(6, 182, 212, 0.25);
  border-radius: 50%;
  animation: spin 35s linear infinite;
}

/* Main Header & Navigation */
.header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
}

.nav {
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font: 700 1.15rem var(--font-heading);
  letter-spacing: -0.03em;
  color: var(--text);
  transition: opacity 0.2s;
}

.brand:hover {
  opacity: 0.85;
}

.brand-icon {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--primary), var(--cyan));
  color: #FFFFFF;
  font: 800 1.3rem var(--font-heading);
  box-shadow: 0 4px 16px rgba(79, 70, 229, 0.2);
}

.navlinks {
  display: flex;
  align-items: center;
  gap: 32px;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
}

.navlinks a {
  transition: color 0.2s ease;
}

.navlinks a:hover {
  color: var(--primary);
}

.navlinks .navcta {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  color: #FFFFFF;
  padding: 10px 22px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.88rem;
  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.2);
  transition: transform 0.2s, box-shadow 0.2s;
}

.navlinks .navcta:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(79, 70, 229, 0.35);
  color: #FFFFFF;
}

.menu-toggle {
  display: none;
}

.menu-toggle svg {
  display: block;
  width: 22px;
  height: 22px;
  stroke: var(--text-main);
  stroke-width: 2.5;
  stroke-linecap: round;
}

/* Light Hero Section */
.hero {
  position: relative;
  padding: 90px 0 75px;
  overflow: hidden;
  background: radial-gradient(circle at 80% 20%, rgba(79, 70, 229, 0.06) 0%, transparent 60%), #FFFFFF;
}

.hero::before {
  content: '';
  position: absolute;
  width: 550px;
  height: 550px;
  right: -200px;
  top: -150px;
  background: rgba(79, 70, 229, 0.08);
  filter: blur(120px);
  border-radius: 50%;
  pointer-events: none;
}

.hero-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1.05fr;
  gap: 48px;
  align-items: center;
}

.hero-copy h2 {
  font: 800 clamp(3.2rem, 5.8vw, 5.8rem) / 0.98 var(--font-heading);
  letter-spacing: -0.065em;
  margin: 22px 0;
  color: var(--text);
}

.hero-copy p {
  color: var(--muted);
  max-width: 520px;
  font-size: 1.08rem;
  line-height: 1.65;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 32px;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 36px;
  color: var(--muted);
  font-size: 0.85rem;
}

.hero-meta b {
  color: var(--primary);
  font-weight: 700;
}

/* Visual Artwork Showcase & Carousel */
.visual-wrap {
  position: relative;
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 28px;
  background: #FFFFFF;
  box-shadow: var(--shadow-lg);
}

.visual-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  padding: 4px 6px 14px;
}

.window-dots {
  display: flex;
  gap: 6px;
}

.window-dots i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #CBD5E1;
  display: block;
}

.window-dots i:first-child { background: var(--primary); }
.window-dots i:nth-child(2) { background: var(--electric); }
.window-dots i:nth-child(3) { background: var(--cyan); }

.visual-canvas {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1.1 / 1;
  border-radius: 18px;
  background: #F8FAFC;
  border: 1px solid var(--border);
  isolation: isolate;
}

.scene {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  transform: scale(0.95);
  transition: opacity 0.6s ease, transform 0.6s ease;
  pointer-events: none;
}

.scene.active {
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
}

.scene svg {
  width: 100%;
  height: 100%;
  display: block;
}

.float-tag {
  position: absolute;
  z-index: 10;
  padding: 10px 16px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text);
  backdrop-filter: blur(12px);
  animation: float 5s ease-in-out infinite;
  display: flex;
  align-items: center;
  gap: 8px;
}

.tag-one { left: -16px; top: 22%; }
.tag-two { right: -16px; bottom: 22%; animation-delay: -2.5s; }

.tag-icon {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  background: linear-gradient(135deg, var(--primary), var(--electric));
  color: #FFFFFF;
  border-radius: 6px;
  font-weight: 900;
  font-size: 0.8rem;
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 6px 4px;
}

.carousel-info strong {
  font: 700 1.05rem var(--font-heading);
  display: block;
  color: var(--text);
}

.carousel-info span {
  font-size: 0.78rem;
  color: var(--muted);
}

.carousel-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.carousel-progress {
  height: 3px;
  background: var(--border);
  border-radius: 3px;
  margin-top: 10px;
  overflow: hidden;
}

.carousel-progress-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--primary), var(--cyan));
  transition: width 0.3s linear;
}

/* Ticker Banner */
.ticker {
  overflow: hidden;
  border-block: 1px solid var(--border);
  background: var(--panel);
  user-select: none;
}

.ticker-track {
  display: flex;
  align-items: center;
  gap: 32px;
  width: max-content;
  padding: 18px 0;
  animation: ticker 28s linear infinite;
}

.ticker-track span {
  font: 700 0.88rem var(--font-heading);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text);
  white-space: nowrap;
}

.ticker-track b {
  color: var(--primary);
  font-size: 1.1rem;
}

/* Section Utility */
.section {
  padding: 100px 0;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 48px;
}

.section-head h2 {
  font: 800 clamp(2.4rem, 5vw, 4.2rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 14px 0 0;
  color: var(--text);
}

.section-head p {
  max-width: 440px;
  color: var(--muted);
  margin: 0;
  font-size: 1.02rem;
}

/* Services Grid */
.services {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.service {
  position: relative;
  overflow: hidden;
  min-height: 260px;
  padding: 28px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--card);
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.3s, box-shadow 0.3s;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.service::after {
  content: '';
  position: absolute;
  width: 120px;
  height: 120px;
  right: -60px;
  bottom: -60px;
  border-radius: 50%;
  background: var(--primary);
  filter: blur(45px);
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}

.service:hover {
  transform: translateY(-8px);
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

.service:hover::after {
  opacity: 0.15;
}

.service-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.service-icon {
  width: 50px;
  height: 50px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.1), rgba(6, 182, 212, 0.1));
  color: var(--primary);
  font-size: 1.4rem;
  font-weight: 700;
}

.service .number {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.service h3 {
  font: 700 1.25rem var(--font-heading);
  margin: 24px 0 10px;
  color: var(--text);
}

.service p {
  font-size: 0.88rem;
  color: var(--muted);
  line-height: 1.6;
  margin: 0;
}

/* Portfolio Section */
.work-section {
  background: var(--panel);
  border-block: 1px solid var(--border);
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 32px;
}

.filter {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 10px 22px;
  background: #FFFFFF;
  color: var(--text);
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 700;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
}

.filter.active, .filter:hover {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  border-color: transparent;
  color: #FFFFFF;
  box-shadow: 0 6px 20px rgba(79, 70, 229, 0.3);
}

.projects {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.project {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s, box-shadow 0.35s;
  display: flex;
  flex-direction: column;
}

.project:hover {
  transform: translateY(-7px);
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

.project[hidden] {
  display: none !important;
}

.project-art {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1.45 / 1;
  background: #F8FAFC;
  width: 100%;
  height: 100%;
}

.project-art svg {
  width: 100%;
  height: 100%;
  display: block;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.project:hover .project-art svg {
  transform: scale(1.05);
}

.concept-badge {
  position: absolute;
  bottom: 14px;
  left: 14px;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.15em;
  color: var(--primary);
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 10px;
  backdrop-filter: blur(8px);
  box-shadow: var(--shadow-sm);
}

.project-info {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 20px 22px;
  background: #FFFFFF;
  margin-top: auto;
}

.project-info h3 {
  font: 700 1.15rem var(--font-heading);
  margin: 0;
  color: var(--text);
}

.project-info p {
  color: var(--muted);
  font-size: 0.8rem;
  margin: 4px 0 0;
}

.project-link {
  width: 38px;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--primary);
  flex-shrink: 0;
  transition: all 0.2s;
}

.project:hover .project-link {
  background: var(--primary);
  color: #FFFFFF;
  border-color: var(--primary);
}

/* Motion Lab Section */
.feature {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 56px;
  border: 1px solid var(--border);
  border-radius: 28px;
  background: radial-gradient(ellipse at 90% 30%, rgba(79, 70, 229, 0.08), transparent 50%), #F5F8FF;
  overflow: hidden;
  position: relative;
  box-shadow: var(--shadow-sm);
}

.feature h2 {
  font: 800 clamp(2.5rem, 5vw, 4.4rem) / 1 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 16px 0 20px;
  color: var(--text);
}

.feature p {
  color: var(--muted);
  max-width: 480px;
  font-size: 1.05rem;
  margin-bottom: 32px;
}

.feature-art {
  position: relative;
  min-height: 320px;
  display: grid;
  place-items: center;
}

.orb {
  width: 190px;
  height: 190px;
  border-radius: 40%;
  background: linear-gradient(140deg, #4F46E5 0%, #2563EB 35%, #06B6D4 70%, #8B5CF6 100%);
  box-shadow: inset -15px -15px 35px rgba(255, 255, 255, 0.4), 0 12px 40px rgba(79, 70, 229, 0.25);
  transform: rotate(25deg);
  animation: float 6s ease-in-out infinite;
}

.orb-ring {
  position: absolute;
  width: 300px;
  height: 120px;
  border: 2px solid rgba(79, 70, 229, 0.4);
  border-radius: 50%;
  transform: rotate(-28deg);
  animation: spin 24s linear infinite;
}

.orb-ring.two {
  width: 320px;
  height: 140px;
  transform: rotate(55deg);
  border-color: rgba(6, 182, 212, 0.4);
  animation-direction: reverse;
}

/* About Mukesh Singh */
.about-grid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 56px;
  align-items: center;
}

.about-art {
  min-height: 400px;
  position: relative;
  display: grid;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 24px;
  background: radial-gradient(circle at 50% 40%, rgba(79, 70, 229, 0.1), transparent 60%), #F5F8FF;
  overflow: hidden;
}

.about-art::before {
  content: 'MUKESH SINGH / CREATIVE DIRECTOR';
  position: absolute;
  bottom: 22px;
  left: 22px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.monogram {
  font: 900 clamp(7rem, 16vw, 13rem) / 1 var(--font-heading);
  letter-spacing: -0.12em;
  color: transparent;
  -webkit-text-stroke: 2px var(--primary);
  text-shadow: 10px 10px 0 rgba(79, 70, 229, 0.12);
  transform: rotate(-6deg);
  user-select: none;
}

.about-copy h2 {
  font: 800 clamp(2.5rem, 5vw, 4.2rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 16px 0;
  color: var(--text);
}

.about-copy p {
  color: var(--muted);
  font-size: 1.05rem;
  margin-bottom: 16px;
}

.skills {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 28px 0 32px;
}

.skills span {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 8px 16px;
  color: var(--text);
  font-size: 0.82rem;
  font-weight: 700;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
}

/* Contact Section & Footer */
.contact {
  padding: 110px 0;
  text-align: center;
  background: radial-gradient(ellipse at 50% 100%, rgba(79, 70, 229, 0.08), transparent 65%), #FFFFFF;
}

.contact h2 {
  font: 800 clamp(2.8rem, 7vw, 5.8rem) / 0.98 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 20px 0;
  color: var(--text);
}

.contact p {
  max-width: 580px;
  margin: 0 auto 32px;
  color: var(--muted);
  font-size: 1.08rem;
}

.contact-actions {
  display: flex;
  justify-content: center;
  gap: 14px;
  flex-wrap: wrap;
}

/* WhatsApp Quotation Form Styles */
.quote-card {
  max-width: 680px;
  margin: 48px auto 40px;
  background: #FFFFFF;
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 44px 36px;
  box-shadow: 0 20px 48px rgba(79, 70, 229, 0.08), 0 4px 12px rgba(17, 24, 39, 0.03);
  text-align: left;
  position: relative;
  overflow: hidden;
}

.quote-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #4F46E5, #2563EB, #06B6D4);
}

.quote-card-head {
  margin-bottom: 28px;
  text-align: center;
}

.quote-card-title {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 3.2vw, 2rem);
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}

.quote-card-sub {
  font-size: 0.95rem;
  color: var(--muted);
  line-height: 1.5;
  margin: 0;
}

.quote-form {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.form-label {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -0.01em;
}

.form-label .req {
  color: #EF4444;
  margin-left: 2px;
}

.form-control {
  width: 100%;
  background: #F8FAFC;
  border: 1.5px solid var(--border);
  border-radius: 12px;
  padding: 14px 16px;
  font-size: 0.95rem;
  font-family: var(--font-body);
  color: var(--text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
  box-sizing: border-box;
  outline: none;
}

.form-control::placeholder {
  color: #94A3B8;
}

.form-control:focus {
  background: #FFFFFF;
  border-color: #4F46E5;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.form-control.field-error {
  border-color: #EF4444;
  background: #FFFBFB;
}

.form-control.field-error:focus {
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.15);
}

select.form-control {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%2364748B' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: right 14px center;
  background-size: 16px;
  padding-right: 40px;
  cursor: pointer;
}

textarea.form-control {
  resize: vertical;
  min-height: 120px;
  line-height: 1.55;
}

.field-error-msg {
  font-size: 0.82rem;
  color: #EF4444;
  display: none;
  margin-top: 2px;
  font-weight: 500;
}

.field-error-msg.visible {
  display: block;
}

.btn-whatsapp-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  padding: 16px 28px;
  background: linear-gradient(135deg, #25D366 0%, #128C7E 100%);
  color: #FFFFFF;
  font-family: var(--font-heading);
  font-size: 1.02rem;
  font-weight: 600;
  border-radius: 12px;
  border: none;
  cursor: pointer;
  box-shadow: 0 10px 24px rgba(37, 211, 102, 0.28);
  transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
  margin-top: 6px;
}

.btn-whatsapp-submit:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 30px rgba(37, 211, 102, 0.35);
  filter: brightness(1.03);
}

.btn-whatsapp-submit:active {
  transform: translateY(0);
  box-shadow: 0 6px 16px rgba(37, 211, 102, 0.24);
}

.btn-whatsapp-submit:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 211, 102, 0.4);
}

.btn-whatsapp-submit svg {
  width: 22px;
  height: 22px;
  fill: #FFFFFF;
  flex-shrink: 0;
}

.quote-status-feedback {
  font-size: 0.9rem;
  padding: 12px 16px;
  border-radius: 10px;
  text-align: center;
  margin-top: 8px;
  display: none;
  line-height: 1.45;
}

.quote-status-feedback.info {
  display: block;
  background: #EFF6FF;
  border: 1px solid #BFDBFE;
  color: #1D4ED8;
}

.quote-status-feedback.error {
  display: block;
  background: #FEF2F2;
  border: 1px solid #FECACA;
  color: #B91C1C;
}

@media (max-width: 640px) {
  .quote-card {
    padding: 32px 20px;
    margin: 36px auto 32px;
    border-radius: 20px;
  }
  .btn-whatsapp-submit {
    padding: 14px 20px;
    font-size: 0.96rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .btn-whatsapp-submit,
  .form-control {
    transition: none !important;
  }
  .btn-whatsapp-submit:hover {
    transform: none !important;
  }
}


/* Premium Responsive Footer Styles */
.footer {
  border-top: 1px solid var(--border);
  padding: 60px 0 32px;
  color: var(--muted);
  font-size: 0.9rem;
  background: #F8FAFC;
  position: relative;
  overflow: hidden;
}

.footer-content {
  display: grid;
  grid-template-columns: 2fr 1fr 2fr;
  gap: 48px;
  margin-bottom: 40px;
}

.footer-brand {
  margin-bottom: 16px;
  display: inline-flex;
  align-items: center;
  gap: 12px;
}

.footer-brand-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text);
}

.footer-founder {
  font-size: 0.95rem;
  color: var(--text);
  margin-bottom: 4px;
}

.footer-tagline {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  background: linear-gradient(135deg, var(--primary) 0%, var(--electric) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 12px;
}

.footer-desc {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--muted);
  max-width: 420px;
}

.footer-heading {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 16px;
  letter-spacing: -0.01em;
}

.footer-nav-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-nav-list a {
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s ease, transform 0.2s ease;
  display: inline-block;
}

.footer-nav-list a:hover,
.footer-nav-list a:focus-visible {
  color: var(--primary);
  transform: translateX(4px);
}

.footer-subtext {
  font-size: 0.88rem;
  line-height: 1.5;
  margin-bottom: 16px;
  color: var(--muted);
}

.footer-social-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.footer-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  min-height: 44px;
  border-radius: 12px;
  background: #FFFFFF;
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 0.88rem;
  font-weight: 600;
  text-decoration: none;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, color 0.2s ease;
}

.footer-action-btn:hover,
.footer-action-btn:focus-visible {
  border-color: var(--primary);
  color: var(--primary);
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(79, 70, 229, 0.12);
}

.footer-action-btn.footer-quote-btn {
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.08) 0%, rgba(6, 182, 212, 0.08) 100%);
  border-color: rgba(79, 70, 229, 0.3);
  color: var(--primary);
}

.footer-action-btn.footer-quote-btn:hover,
.footer-action-btn.footer-quote-btn:focus-visible {
  background: linear-gradient(135deg, var(--primary) 0%, var(--electric) 100%);
  color: #FFFFFF;
  border-color: transparent;
  box-shadow: 0 8px 20px rgba(79, 70, 229, 0.25);
}

.footer-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
}

.footer-bottom-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.85rem;
  color: var(--muted);
  flex-wrap: wrap;
  gap: 12px;
}

.footer-credit strong {
  color: var(--text);
}

/* Reveal animation */
.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.7s cubic-bezier(0.16, 1, 0.3, 1), transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.blogger-hidden {
  display: none !important;
}

/* Animations */
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-14px); }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@keyframes ticker {
  to { transform: translateX(-50%); }
}

/* Responsive Design */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .hero-copy {
    text-align: center;
  }
  .hero-copy p {
    margin-inline: auto;
  }
  .hero-actions, .hero-meta {
    justify-content: center;
  }
  .visual-wrap {
    width: min(100%, 680px);
    margin: auto;
  }
  .services {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .projects {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .about-grid {
    gap: 36px;
  }
  .feature {
    gap: 24px;
    padding: 40px;
  }
}

@media (max-width: 768px) {
  .container {
    width: calc(100% - 32px);
  }
  .nav {
    height: 70px;
  }
  .menu-toggle {
    display: inline-flex !important;
  }
  .navlinks {
    display: none;
    position: absolute;
    left: 0;
    right: 0;
    top: 70px;
    padding: 24px;
    background: #FFFFFF;
    border-bottom: 1px solid var(--border);
    flex-direction: column;
    align-items: stretch;
    gap: 18px;
    box-shadow: var(--shadow-lg);
  }
  .navlinks.open {
    display: flex;
  }
  .navlinks .navcta {
    text-align: center;
  }
  .hero {
    padding: 56px 0 48px;
  }
  .hero-copy h2 {
    font-size: clamp(2.8rem, 11vw, 4.4rem);
  }
  .visual-wrap {
    padding: 12px;
    border-radius: 20px;
  }
  .float-tag {
    font-size: 0.68rem;
    padding: 8px 12px;
  }
  .tag-one { left: -6px; }
  .tag-two { right: -6px; }
  .section {
    padding: 70px 0;
  }
  .section-head {
    display: block;
    margin-bottom: 32px;
  }
  .section-head p {
    margin-top: 14px;
  }
  .services {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .service {
    padding: 20px;
    min-height: auto;
  }
  .projects {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .feature {
    grid-template-columns: 1fr;
    padding: 32px 24px;
    gap: 12px;
  }
  .feature-art {
    min-height: 240px;
    grid-row: 1;
  }
  .orb { width: 140px; height: 140px; }
  .orb-ring { width: 230px; height: 95px; }
  .orb-ring.two { width: 250px; height: 110px; }
  .about-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .about-art { min-height: 280px; }
  .monogram { font-size: 8.5rem; }
  .contact { padding: 75px 0; }
  .footer-content {
    grid-template-columns: 1fr;
    gap: 36px;
  }
  .footer-social-grid {
    grid-template-columns: 1fr;
  }
  .footer-bottom-inner {
    flex-direction: column;
    text-align: center;
    gap: 8px;
  }
}

@media (max-width: 480px) {
  .footer {
    padding: 44px 0 24px;
  }
  .footer-content {
    gap: 28px;
  }
  .footer-action-btn {
    width: 100%;
    justify-content: flex-start;
  }
}

@media (max-width: 390px) {
  .container {
    width: calc(100% - 24px);
  }
  .brand { font-size: 0.98rem; }
  .brand-icon { width: 34px; height: 34px; font-size: 1.1rem; }
  .hero-copy h2 { font-size: 2.6rem; }
  .hero-actions .btn { width: 100%; }
  .carousel-nav { flex-direction: column; align-items: flex-start; gap: 8px; }
  .intro h1 { font-size: 2.2rem; }
  .intro .btn { width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

/* ==========================================================================
   REELS & VERTICAL VIDEO SHOWCASE SECTION
   ========================================================================== */
.reels-section {
  background: radial-gradient(ellipse at 50% 0%, rgba(79, 70, 229, 0.05), transparent 70%), #FFFFFF;
  position: relative;
  overflow: hidden;
}

.reels-category-filters {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-bottom: 36px;
}

.reel-filter-btn {
  padding: 10px 22px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: #FFFFFF;
  color: var(--text);
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
}

.reel-filter-btn:hover,
.reel-filter-btn.active {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  color: #FFFFFF;
  border-color: transparent;
  box-shadow: 0 6px 20px rgba(79, 70, 229, 0.3);
}

.reels-carousel-container {
  position: relative;
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 10px 0;
}

.reels-carousel-track-wrapper {
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: calc(50% - 140px);
  -webkit-overflow-scrolling: touch;
  /* Let the browser handle BOTH pan axes: it locks each gesture to its dominant axis, so a
     horizontal swipe scrolls the carousel without dragging the page vertically. (The previous
     "pan-y" disabled native horizontal swiping on the carousel entirely.) */
  touch-action: manipulation;
  overscroll-behavior-x: contain;
  padding: 20px 0;
  scrollbar-width: none;
}
.reels-carousel-track-wrapper::-webkit-scrollbar {
  display: none;
}

.reels-carousel-track {
  display: flex;
  align-items: center;
  gap: 28px;
  width: max-content;
  margin: 0 auto;
  touch-action: manipulation;
}

/* Vertical Reel Card Frame (9:16 aspect ratio) */
.reel-card {
  flex: 0 0 280px;
  width: 280px;
  scroll-snap-align: center;
  scroll-snap-stop: always;
  touch-action: manipulation;
  position: relative;
  border-radius: 24px;
  background: #000000;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.35s ease, box-shadow 0.35s ease;
  opacity: 0.65;
  transform: scale(0.92);
  user-select: none;
}

.reel-card.active {
  opacity: 1;
  transform: scale(1);
  box-shadow: 0 20px 48px rgba(79, 70, 229, 0.22);
  border-color: rgba(79, 70, 229, 0.4);
  z-index: 5;
}

.reel-frame-inner {
  position: relative;
  width: 100%;
  aspect-ratio: 9 / 16;
  background: #111827;
  overflow: hidden;
  border-radius: 23px;
}

.reel-thumbnail-wrap {
  position: absolute;
  inset: 0;
  z-index: 2;
  background-size: cover;
  background-position: center;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 16px;
  transition: opacity 0.35s ease;
}

.reel-thumbnail-wrap::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0.4) 0%, rgba(0,0,0,0) 40%, rgba(0,0,0,0.85) 100%);
  z-index: 1;
  pointer-events: none;
}

.reel-badge-category {
  position: relative;
  z-index: 2;
  align-self: flex-start;
  padding: 6px 14px;
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(8px);
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.reel-play-btn-wrap {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 3;
  cursor: pointer;
  border-radius: 50%;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.reel-play-btn {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: linear-gradient(135deg, #4F46E5, #2563EB, #06B6D4);
  color: #FFFFFF;
  display: grid;
  place-items: center;
  box-shadow: 0 10px 30px rgba(79, 70, 229, 0.4);
  transition: transform 0.25s ease;
}

.reel-play-btn svg {
  width: 26px;
  height: 26px;
  fill: #FFFFFF;
  margin-left: 3px;
}

.reel-card:hover .reel-play-btn-wrap {
  transform: translate(-50%, -50%) scale(1.1);
}

.reel-meta-bottom {
  position: relative;
  z-index: 2;
  color: #FFFFFF;
}

.reel-cover-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
  transition: transform 0.4s ease;
}

.reel-card:hover .reel-cover-img {
  transform: scale(1.04);
}

.reel-meta-title {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 6px;
  text-shadow: 0 2px 4px rgba(0,0,0,0.6);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  word-break: break-word;
}

.reel-meta-desc {
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.85);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* YouTube IFrame Container inside Reel Card */
.reel-iframe-container {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
}

.reel-iframe-container iframe {
  width: 100%;
  height: 100%;
  border: none;
  display: block;
}

/* Error & Loading States inside Reel Card */
.reel-status-overlay {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: #0F172A;
  color: #FFFFFF;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  text-align: center;
  gap: 12px;
}

.reel-status-overlay.hidden {
  display: none;
}

.reel-spinner {
  width: 36px;
  height: 36px;
  border: 3px solid rgba(255,255,255,0.2);
  border-top-color: var(--cyan);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

.reel-error-text {
  font-size: 0.82rem;
  color: #F87171;
}

.reel-retry-btn {
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(255,255,255,0.15);
  color: #FFFFFF;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid rgba(255,255,255,0.2);
  transition: background 0.2s ease;
}

.reel-retry-btn:hover {
  background: rgba(255,255,255,0.3);
}

/* Carousel Navigation Footer */
.reels-carousel-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 580px;
  margin: 28px auto 0;
  padding: 0 16px;
}

.reels-counter {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.1rem;
  color: var(--text);
  letter-spacing: 0.05em;
}

.reels-counter span {
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
}

/* Sound / Fullscreen / Carousel Control Row */
.reels-control-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Honest fallback when every YouTube thumbnail size fails (no fabricated cover art) */
.reel-cover-missing {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
  background: #111827;
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.8rem;
  font-weight: 600;
}

.reel-thumbnail-wrap.no-cover .reel-cover-missing {
  display: flex;
}

/* Short explanatory note inside empty states (e.g. skipped posts) */
.feed-state-note {
  margin: 12px auto 0;
  max-width: 460px;
  font-size: 0.8rem;
  color: var(--muted);
}

/* ==========================================================================
   GRAPHIC DESIGN GALLERY SECTION
   ========================================================================== */
.graphics-section {
  background: var(--panel);
  border-block: 1px solid var(--border);
}

.graphics-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  margin-top: 32px;
}

.graphic-card {
  position: relative;
  border-radius: 18px;
  background: #FFFFFF;
  border: 1px solid var(--border);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.35s ease, border-color 0.35s ease;
  display: flex;
  flex-direction: column;
}

.graphic-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: var(--primary);
}

.graphic-card[hidden] {
  display: none !important;
}

.graphic-image-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  background: #F1F5F9;
  overflow: hidden;
}

.graphic-image-wrap img,
.graphic-image-wrap svg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.graphic-card:hover .graphic-image-wrap img,
.graphic-card:hover .graphic-image-wrap svg {
  transform: scale(1.06);
}

.graphic-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--primary);
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 8px;
  backdrop-filter: blur(8px);
  z-index: 2;
}

.graphic-info {
  padding: 16px 18px;
  background: #FFFFFF;
}

.graphic-info h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: var(--text);
  margin: 0 0 4px;
}

.graphic-info p {
  font-size: 0.78rem;
  color: var(--muted);
  margin: 0;
}

/* Graphics post without a usable image, or an image that failed to load: neutral, clearly
   labelled panel. Never a generated/gradient placeholder pretending to be artwork. */
.graphic-missing,
.graphic-img-failed-msg {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px;
  text-align: center;
  background: #F1F5F9;
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 600;
}

.graphic-img-failed-msg {
  display: none;
}

.graphic-image-wrap.img-failed .graphic-img-failed-msg {
  display: flex;
}

.graphic-card--no-image {
  cursor: default;
}

.graphic-card--no-image:hover {
  transform: none;
  border-color: var(--border);
  box-shadow: var(--shadow-sm);
}

.graphic-card:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.graphic-post-link {
  display: inline-block;
  margin-top: 8px;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--primary);
}

/* ==========================================================================
   LIGHTBOX / MODAL FOR GRAPHIC PREVIEW
   ========================================================================== */
.lightbox-modal {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: rgba(17, 24, 39, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.lightbox-modal.open {
  opacity: 1;
  visibility: visible;
}

.lightbox-content-wrap {
  position: relative;
  max-width: 900px;
  width: 100%;
  background: #FFFFFF;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 25px 60px rgba(0,0,0,0.3);
  display: flex;
  flex-direction: column;
  max-height: 90vh;
  transform: scale(0.92);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.lightbox-modal.open .lightbox-content-wrap {
  transform: scale(1);
}

.lightbox-body {
  position: relative;
  flex: 1;
  display: grid;
  place-items: center;
  background: #000000;
  overflow: hidden;
  max-height: 70vh;
}

.lightbox-body img,
.lightbox-body svg {
  max-width: 100%;
  max-height: 70vh;
  object-fit: contain;
  display: block;
}

.lightbox-meta-bar {
  padding: 20px 24px;
  background: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid var(--border);
}

.lightbox-meta-title {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text);
}

.lightbox-meta-cat {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 2px;
}

.lightbox-post-link {
  flex-shrink: 0;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--primary);
  white-space: nowrap;
}

.lightbox-post-link[hidden] {
  display: none;
}

.lightbox-close-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 10;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--border);
  color: var(--text);
  display: grid;
  place-items: center;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: transform 0.2s ease, background 0.2s ease;
}

.lightbox-close-btn:hover {
  transform: scale(1.08);
  background: #FFFFFF;
}

.lightbox-nav-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--border);
  color: var(--text);
  display: grid;
  place-items: center;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: transform 0.2s ease, background 0.2s ease;
}

.lightbox-nav-btn:hover {
  transform: translateY(-50%) scale(1.08);
  background: #FFFFFF;
}

.lightbox-nav-prev { left: 16px; }
.lightbox-nav-next { right: 16px; }

/* Responsive Adjustments for Reels and Graphics */
@media (max-width: 1024px) {
  .graphics-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .reels-carousel-track-wrapper {
    scroll-padding-inline: calc(50% - 130px);
  }
  .reels-carousel-track {
    gap: 16px;
  }
  .reel-card {
    flex: 0 0 260px;
    width: 260px;
  }
  .graphics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
  }
  .lightbox-content-wrap {
    max-height: 95vh;
  }
  .lightbox-body {
    max-height: 60vh;
  }
  .lightbox-meta-bar {
    padding: 14px 18px;
  }
}

@media (max-width: 480px) {
  .reels-carousel-track-wrapper {
    scroll-padding-inline: calc(50% - 120px);
  }
  .reel-card {
    flex: 0 0 240px;
    width: 240px;
  }
  .reels-carousel-footer {
    flex-direction: column;
    gap: 14px;
  }
}

@media (max-width: 360px) {
  .reels-carousel-track-wrapper {
    scroll-padding-inline: calc(50% - 110px);
  }
  .reel-card {
    flex: 0 0 220px;
    width: 220px;
    border-radius: 20px;
  }
  .reel-frame-inner {
    border-radius: 19px;
  }
  .reel-play-btn {
    width: 54px;
    height: 54px;
  }
  .reel-play-btn svg {
    width: 22px;
    height: 22px;
  }
  .reel-meta-title {
    font-size: 0.95rem;
  }
}

body.script:
//
(function(){
  /* ==========================================================================
     STUDIO CONFIGURATION
     Central authoritative configuration for Singh Creative Studio.
     Replace or customize any of these values as needed.
     ========================================================================== */
  var STUDIO_CONFIG = {
    brandName: 'Singh Creative Studio',
    founder: 'Mukesh Singh',
    tagline: 'Ideas Made Visible.',
    email: 'dharmjeetsingh958@gmail.com',
    phone: '+919334603912',
    phoneDisplay: '+91 9334603912',
    quoteTarget: '#contact',
    social: {
      instagram: 'https://www.instagram.com/getsynfusion/',
      facebook: 'https://www.facebook.com/getsynfusion',
      youtube: 'https://www.youtube.com/@getsynfusion',
      whatsapp: 'https://wa.me/919334603912'
    },
    bloggerFeed: {
      // The feed is always read from THIS blog. Its address comes from Blogger itself
      // (data:blog.homepageUrl / data:blog.blogId rendered into #scsBlogMeta) or from the page's
      // own origin. No blog hostname is hardcoded here.
      feedPath: '/feeds/posts/default',
      // Strict, case-insensitive, whole-label matching. A post appears in a section ONLY when it
      // carries that section's label. A post carrying BOTH labels is a labeling conflict: it is
      // shown in NEITHER section and a console warning asks for the labels to be corrected.
      reelsLabel: 'Reels',
      graphicsLabel: 'Graphics',
      maxResultsPerPage: 50,
      maxTotalPosts: 150,
      requestTimeoutMs: 10000
    },
    youtubePlayerVars: {
      autoplay: 0,
      controls: 1,
      modestbranding: 1,
      rel: 0,
      playsinline: 1
    }
  };

  // Cinematic Intro Screen handling with Explicit State Machine:
  // States: 'intro-active' -> 'intro-transitioning' -> 'intro-complete'
  var intro = document.getElementById('introScreen');
  var enterBtn = document.getElementById('enterStudio');
  var introState = 'intro-active';
  var introFallbackTimer = null;

  // Ensure scroll is at top and locked while intro is active
  if (intro && !intro.classList.contains('hidden')) {
    document.body.classList.remove('intro-dismissed');
    document.body.style.overflow = 'hidden';
    window.scrollTo(0, 0);
  }

  function finishIntroTransition() {
    if (introState === 'intro-complete') return;
    introState = 'intro-complete';

    if (introFallbackTimer) {
      clearTimeout(introFallbackTimer);
      introFallbackTimer = null;
    }

    if (intro) {
      intro.classList.remove('transitioning');
      intro.classList.add('hidden');
      intro.setAttribute('aria-hidden', 'true');
    }

    document.body.classList.add('intro-dismissed');
    document.body.style.overflow = '';
    window.scrollTo(0, 0);
  }

  function startCinematicTransition() {
    if (introState !== 'intro-active') return;
    introState = 'intro-transitioning';

    if (enterBtn) {
      enterBtn.classList.add('active-cta');
      enterBtn.setAttribute('disabled', 'disabled');
    }

    var prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (prefersReducedMotion) {
      finishIntroTransition();
      return;
    }

    if (intro) {
      intro.classList.add('transitioning');
      var onTransitionEnd = function(e) {
        if (e.target === intro) {
          intro.removeEventListener('transitionend', onTransitionEnd);
          finishIntroTransition();
        }
      };
      intro.addEventListener('transitionend', onTransitionEnd);
    }

    // Safety fallback timer in case transitionend does not fire
    introFallbackTimer = setTimeout(finishIntroTransition, 1000);
  }

  if (enterBtn) {
    enterBtn.addEventListener('click', function(e) {
      e.preventDefault();
      startCinematicTransition();
    });
  }

  // Mobile Navigation Toggle
  var menuBtn = document.getElementById('menuToggle');
  var navLinks = document.getElementById('navLinks');

  if (menuBtn && navLinks) {
    menuBtn.addEventListener('click', function(){
      var isOpen = navLinks.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });

    navLinks.querySelectorAll('a').forEach(function(link){
      link.addEventListener('click', function(){
        navLinks.classList.remove('open');
        menuBtn.setAttribute('aria-expanded', 'false');
      });
    });
  }

  // Automatic Visual Carousel
  var scenes = [].slice.call(document.querySelectorAll('.scene'));
  var carouselTitle = document.getElementById('carouselTitle');
  var carouselSub = document.getElementById('carouselSub');
  var carouselProgress = document.getElementById('carouselProgress');
  var btnPrev = document.getElementById('carouselPrev');
  var btnNext = document.getElementById('carouselNext');
  var btnToggle = document.getElementById('carouselToggle');
  var togglePauseIcon = document.getElementById('togglePauseIcon');

  var curIdx = 0;
  var timer = null;
  var isPaused = false;
  var intervalMs = 4000;
  var prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function setProgress(percent) {
    if (carouselProgress) {
      carouselProgress.style.width = percent + '%';
    }
  }

  function showSlide(idx) {
    if (!scenes.length) return;
    curIdx = (idx + scenes.length) % scenes.length;
    scenes.forEach(function(s, i) {
      s.classList.toggle('active', i === curIdx);
    });

    var activeScene = scenes[curIdx];
    if (activeScene) {
      if (carouselTitle) carouselTitle.textContent = activeScene.getAttribute('data-title') || '';
      if (carouselSub) carouselSub.textContent = activeScene.getAttribute('data-sub') || '';
    }

    setProgress(((curIdx + 1) / scenes.length) * 100);
  }

  function startCarousel() {
    stopCarousel();
    if (!isPaused && !prefersReducedMotion && !document.hidden) {
      timer = setInterval(function(){
        showSlide(curIdx + 1);
      }, intervalMs);
    }
  }

  function stopCarousel() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  if (scenes.length) {
    showSlide(0);
    startCarousel();

    if (btnPrev) {
      btnPrev.addEventListener('click', function(){
        showSlide(curIdx - 1);
        startCarousel();
      });
    }

    if (btnNext) {
      btnNext.addEventListener('click', function(){
        showSlide(curIdx + 1);
        startCarousel();
      });
    }

    if (btnToggle) {
      btnToggle.addEventListener('click', function(){
        isPaused = !isPaused;
        btnToggle.setAttribute('aria-label', isPaused ? 'Play carousel' : 'Pause carousel');
        if (togglePauseIcon) {
          togglePauseIcon.innerHTML = isPaused ?
            "<polygon points='5 3 19 12 5 21 5 3'/>" :
            "<rect x='6' y='4' width='4' height='16'/><rect x='14' y='4' width='4' height='16'/>";
        }
        if (isPaused) stopCarousel();
        else startCarousel();
      });
    }

    var visualCanvas = document.getElementById('visualCanvas');
    if (visualCanvas) {
      visualCanvas.addEventListener('mouseenter', stopCarousel);
      visualCanvas.addEventListener('mouseleave', function(){
        if (!isPaused) startCarousel();
      });

      var touchStartX = 0;
      visualCanvas.addEventListener('touchstart', function(e){
        if (e.touches.length) touchStartX = e.touches[0].clientX;
      }, {passive: true});

      visualCanvas.addEventListener('touchend', function(e){
        if (e.changedTouches.length) {
          var diff = e.changedTouches[0].clientX - touchStartX;
          if (Math.abs(diff) > 40) {
            showSlide(curIdx + (diff < 0 ? 1 : -1));
            startCarousel();
          }
        }
      }, {passive: true});
    }

    document.addEventListener('visibilitychange', function(){
      if (document.hidden) stopCarousel();
      else if (!isPaused) startCarousel();
    });
  }

  // Portfolio Filter handling (scoped to the portfolio section so it never touches the
  // Graphics gallery filters, which share the .filter class)
  var filterButtons = document.querySelectorAll('#work .filter[data-filter]');
  var projectCards = document.querySelectorAll('.project');

  filterButtons.forEach(function(btn){
    btn.addEventListener('click', function(){
      var filterValue = btn.getAttribute('data-filter');

      filterButtons.forEach(function(b){ b.classList.remove('active'); });
      btn.classList.add('active');

      projectCards.forEach(function(card){
        var tags = (card.getAttribute('data-tags') || '').split(' ');
        if (filterValue === 'all' || tags.indexOf(filterValue) !== -1) {
          card.removeAttribute('hidden');
        } else {
          card.setAttribute('hidden', 'hidden');
        }
      });
    });
  });

  // Intersection Observer for Section Reveals
  if ('IntersectionObserver' in window) {
    var observer = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting) {
          e.target.classList.add('visible');
          observer.unobserve(e.target);
        }
      });
    }, { threshold: 0.1 });

    document.querySelectorAll('.reveal').forEach(function(el){
      observer.observe(el);
    });
  } else {
    document.querySelectorAll('.reveal').forEach(function(el){
      el.classList.add('visible');
    });
  }

  if (prefersReducedMotion) {
    document.querySelectorAll('.reveal').forEach(function(el){
      el.classList.add('visible');
    });
  }

  // Dynamic Year
  var yearEl = document.getElementById('yearNow');
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }

  /* ==========================================================================
     SINGH CREATIVE STUDIO — REELS & GRAPHICS SYSTEM
     Every Reel and every Graphics card comes from a published Blogger post.
     This theme contains NO demo, sample or placeholder content; when there are
     no matching posts the sections show an honest empty state.

     Classification rules (strict, case-insensitive, whole-label match):
       1. A post labeled "Graphics" appears ONLY in the Graphics gallery.
          Artwork = real images uploaded in the post body (entry.content.$t), then the
          summary (entry.summary.$t), then entry.media$thumbnail as a last resort.
          YouTube thumbnails are never used as artwork. An incidental YouTube link
          does not make a Graphics post a Reel.
       2. A post labeled "Reels" appears ONLY in the Reels carousel, and only when a
          valid 11-character YouTube video ID is found (watch, youtu.be, Shorts, embed,
          live, iframe or Blogger youtube-src-id formats). The cover is the YouTube
          thumbnail generated from that ID. Reels posts without a valid ID are skipped
          and reported; no video is ever invented.
       3. Conflict rule: a post labeled BOTH "Reels" and "Graphics" is shown in NEITHER
          section (never duplicated, never guessed). A console warning names the post
          and asks for one of the two labels to be removed in Blogger.
       4. Posts with neither label are ignored.
     Optional extra labels only choose the filter chip inside a section:
       Graphics: Logo Design, Social Media Posts, YouTube Thumbnails,
                 Posters & Banners, Advertising Creatives, Visual Branding
       Reels:    2D Animation, 3D Animation, Video Editing, AI Product Ads,
                 Animation
     ========================================================================== */

  // Filled at runtime from the content feed only (see discoverBloggerPosts). Shapes:
  //   Reel:    { id, postKey, title, youtubeId, category, badge, description, postUrl, publishedDate }
  //   Graphic: { id, postKey, title, image, imageFallback, imageCount, category, badge,
  //              categoryLabel, postUrl, publishedDate }   (image is '' when the post has none)
  var REELS_DATA = [];
  var GRAPHICS_DATA = [];

  // Global YouTube API Management Variables
  var ytApiLoaded = false;
  var ytApiLoading = false;
  var activeYtPlayer = null;
  var activeYtIframeId = null;
  var isMuted = false;

  // Smart Reel Playback State Management
  // Tracks per-reel playback state to support visibility-based auto-pause/resume
  var reelPlaybackStates = {};
  var activePlayingReelId = null;
  var isAutoPausingOrResuming = false;
  var reelsIntersectionObserver = null;

  function getReelPlaybackState(reelId) {
    if (!reelPlaybackStates[reelId]) {
      reelPlaybackStates[reelId] = {
        reelId: reelId,
        wasPlayingBeforeHidden: false,
        isAutoPaused: false,
        isManuallyPaused: false,
        isPlaying: false,
        isReady: false,
        resumePending: false,
        player: null,
        containerId: null,
        index: -1
      };
    }
    return reelPlaybackStates[reelId];
  }


  // Active Reels Carousel State
  var filteredReels = REELS_DATA.slice();
  var activeReelIndex = 0;
  var isCarouselProgrammaticScroll = false;
  var carouselProgrammaticTimer = null;

  // Registered callbacks waiting for YouTube API ready
  var ytReadyCallbacks = [];

  // Helper to load YouTube IFrame API safely, idempotently, and without multiple script injections
  function loadYouTubeIframeApi(callback) {
    if (window.YT && typeof window.YT.Player === 'function') {
      ytApiLoaded = true;
      if (typeof callback === 'function') callback();
      return;
    }

    if (typeof callback === 'function') {
      ytReadyCallbacks.push(callback);
    }

    if (ytApiLoading) return;
    ytApiLoading = true;

    // Preserve any existing window.onYouTubeIframeAPIReady handler
    var existingHandler = window.onYouTubeIframeAPIReady;
    window.onYouTubeIframeAPIReady = function() {
      ytApiLoaded = true;
      ytApiLoading = false;
      if (typeof existingHandler === 'function') {
        try { existingHandler(); } catch (e) {}
      }
      while (ytReadyCallbacks.length) {
        var cb = ytReadyCallbacks.shift();
        try { cb(); } catch (e) {}
      }
    };

    // Check if script tag is already in DOM
    var existingScript = document.querySelector('script[src*="youtube.com/iframe_api"]');
    if (!existingScript) {
      var tag = document.createElement('script');
      tag.src = 'https://www.youtube.com/iframe_api';
      tag.async = true;
      var firstScript = document.getElementsByTagName('script')[0];
      if (firstScript && firstScript.parentNode) {
        firstScript.parentNode.insertBefore(tag, firstScript);
      } else {
        (document.head || document.body).appendChild(tag);
      }
    }
  }

  // Centralized YouTube Player Cleanup & Stop
  function cleanupActivePlayer(options) {
    var opts = options || {};
    var preserveState = opts.preserveState === true;

    if (activePlayingReelId && !preserveState) {
      var oldState = getReelPlaybackState(activePlayingReelId);
      oldState.isPlaying = false;
      oldState.wasPlayingBeforeHidden = false;
      oldState.isAutoPaused = false;
      oldState.isManuallyPaused = false;
      oldState.isReady = false;
      oldState.resumePending = false;
      oldState.player = null;
    }

    if (activeYtPlayer) {
      try {
        if (typeof activeYtPlayer.stopVideo === 'function') {
          activeYtPlayer.stopVideo();
        }
        if (typeof activeYtPlayer.destroy === 'function') {
          activeYtPlayer.destroy();
        }
      } catch (e) {}
      activeYtPlayer = null;
    }
    activeYtIframeId = null;
    if (!preserveState) {
      activePlayingReelId = null;
    }

    // Reset iframe containers visually
    var iframeContainers = document.querySelectorAll('.reel-iframe-container');
    iframeContainers.forEach(function(el) {
      el.innerHTML = '';
    });

    var thumbWraps = document.querySelectorAll('.reel-thumbnail-wrap');
    thumbWraps.forEach(function(el) {
      el.style.opacity = '1';
      el.style.pointerEvents = 'auto';
    });

    var statusOverlays = document.querySelectorAll('.reel-status-overlay');
    statusOverlays.forEach(function(el) {
      el.classList.add('hidden');
    });
  }

  // ---------------------------------------------------------------------------
  // Feed loading / error state shared by the Reels and Graphics sections
  // ---------------------------------------------------------------------------
  var bloggerFeedState = {
    isLoading: true,
    hasLoadedOnce: false,
    hasSucceededOnce: false,
    reelsError: false,
    graphicsError: false,
    reelsErrorMsg: '',
    graphicsErrorMsg: '',
    // Posts that matched a section label but could not be shown (reported, never faked)
    notes: { reelsWithoutVideo: [], conflicts: [] }
  };

  function feedLog(level, message, detail) {
    if (typeof console === 'undefined') return;
    var fn = console[level] || console.log;
    try {
      if (detail !== undefined) fn.call(console, '[Blogger Feed] ' + message, detail);
      else fn.call(console, '[Blogger Feed] ' + message);
    } catch (e) {}
  }

  // Safe HTML escaping (text and attribute contexts) and entity decoding
  function escapeHtml(str) {
    if (str === null || str === undefined || str === '') return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function decodeHtmlEntities(str) {
    if (!str) return '';
    // A <textarea> parses its content as RCDATA: entities are decoded, no elements are created.
    var txt = document.createElement('textarea');
    txt.innerHTML = String(str);
    return txt.value;
  }

  // Accept only absolute http(s) URLs (protocol-relative becomes https). Characters that could
  // break out of an HTML attribute are percent-encoded; callers still escapeHtml() on output.
  function safeHttpUrl(url) {
    if (!url || typeof url !== 'string') return '';
    var u = url.trim();
    if (u.indexOf('//') === 0) u = 'https:' + u;
    if (!/^https?:\/\/[^\/\s?#]+/i.test(u)) return '';
    // Note: encodeURIComponent() leaves ' unescaped, so quotes are mapped explicitly.
    var unsafe = { '"': '%22', "'": '%27', '<': '%3C', '>': '%3E', '`': '%60', '\\': '%5C' };
    return u.replace(/[\s"'<>`\\]/g, function(ch) { return unsafe[ch] || encodeURIComponent(ch); });
  }

  // Parse untrusted post HTML into an inert document: scripts never run, images never load.
  function parseHtmlInert(html) {
    if (!html || typeof DOMParser !== 'function') return null;
    try {
      var doc = new DOMParser().parseFromString('<!DOCTYPE html><html><body>' + html + '</body></html>', 'text/html');
      return (doc && doc.body) ? doc : null;
    } catch (e) {
      return null;
    }
  }

  function htmlToPlainText(html) {
    if (!html) return '';
    var text = '';
    var doc = parseHtmlInert(html);
    if (doc) {
      var drop = doc.body.querySelectorAll('script, style, noscript, iframe, template');
      for (var i = 0; i < drop.length; i++) {
        if (drop[i].parentNode) drop[i].parentNode.removeChild(drop[i]);
      }
      text = doc.body.textContent || '';
    } else {
      text = decodeHtmlEntities(String(html).replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]*>/g, ' '));
    }
    return text.replace(/https?:\/\/\S+/g, ' ').replace(/\s+/g, ' ').trim();
  }

  // ---------------------------------------------------------------------------
  // YouTube video ID extraction (Reels)
  // ---------------------------------------------------------------------------
  var YT_ID_RE = /^[A-Za-z0-9_-]{11}$/;

  function isValidYouTubeId(id) {
    return typeof id === 'string' && YT_ID_RE.test(id);
  }

  // Each pattern captures exactly 11 ID characters and refuses longer tokens, so a malformed
  // link is rejected instead of being truncated into a wrong video.
  var YT_URL_PATTERNS = [
    // youtube.com / youtube-nocookie.com: /embed/ID, /shorts/ID, /live/ID, /v/ID, /e/ID
    /youtube(?:-nocookie)?\.com\/(?:embed|shorts|live|v|e)\/([A-Za-z0-9_-]{11})(?![A-Za-z0-9_-])/i,
    // youtube.com/watch?v=ID (any subdomain, v= may follow other query parameters)
    /youtube\.com\/watch\/?\?(?:[^"'\s<>#]*?[&;])?v=([A-Za-z0-9_-]{11})(?![A-Za-z0-9_-])/i,
    // youtu.be/ID
    /youtu\.be\/([A-Za-z0-9_-]{11})(?![A-Za-z0-9_-])/i
  ];

  // Extract a YouTube ID from a URL, plain text or HTML (including <iframe src="...">).
  function extractYouTubeIdFromText(text) {
    if (!text || typeof text !== 'string') return null;
    var candidates = [text];
    var decoded = decodeHtmlEntities(text);
    if (decoded !== text) candidates.push(decoded);
    for (var c = 0; c < candidates.length; c++) {
      for (var p = 0; p < YT_URL_PATTERNS.length; p++) {
        var m = candidates[c].match(YT_URL_PATTERNS[p]);
        if (m && isValidYouTubeId(m[1])) return m[1];
      }
    }
    return null;
  }

  // Look for the Reel's video in priority order: embedded players, Blogger's youtube-src-id,
  // links, raw body text, summary, and finally Blogger's media$thumbnail (img.youtube.com/vi/ID/).
  function extractYouTubeIdFromPost(contentHtml, summaryHtml, mediaThumbUrl) {
    var doc = parseHtmlInert(contentHtml);
    if (doc) {
      var frames = doc.body.querySelectorAll('iframe, embed, object');
      for (var i = 0; i < frames.length; i++) {
        var attrId = frames[i].getAttribute('youtube-src-id') || '';
        if (isValidYouTubeId(attrId)) return attrId;
        var frameId = extractYouTubeIdFromText(frames[i].getAttribute('src') || frames[i].getAttribute('data') || frames[i].getAttribute('data-src') || '');
        if (frameId) return frameId;
      }
      var links = doc.body.querySelectorAll('a[href]');
      for (var j = 0; j < links.length; j++) {
        var linkId = extractYouTubeIdFromText(links[j].getAttribute('href') || '');
        if (linkId) return linkId;
      }
    }
    var fromBody = extractYouTubeIdFromText(contentHtml || '');
    if (fromBody) return fromBody;
    var fromSummary = extractYouTubeIdFromText(summaryHtml || '');
    if (fromSummary) return fromSummary;
    if (mediaThumbUrl) {
      var t = String(mediaThumbUrl).match(/(?:img\.youtube\.com|i\d?\.ytimg\.com)\/vi(?:_webp)?\/([A-Za-z0-9_-]{11})\//i);
      if (t && isValidYouTubeId(t[1])) return t[1];
    }
    return null;
  }

  // ---------------------------------------------------------------------------
  // Artwork image extraction (Graphics)
  // ---------------------------------------------------------------------------
  var BLOGGER_IMAGE_HOST_RE = /^https?:\/\/(?:blogger\.googleusercontent\.com|lh\d+\.googleusercontent\.com|(?:\d+\.)?bp\.blogspot\.com)\//i;
  // Blogger size/crop modifiers: s320, s1600, w640-h360, s72-c, s72-w640-h360-c, s1600-rw ...
  var BLOGGER_SIZE_TOKEN_RE = /^[swh]\d+(?:-[a-z0-9]+)*$/i;
  // Never artwork: YouTube/Vimeo video thumbnails, Blogger UI icons, feed trackers.
  var NON_ARTWORK_IMAGE_RE = /(?:ytimg\.com|img\.youtube\.com|youtube\.com\/vi\/|vimeocdn\.com|blogblog\.com|blogger\.com\/img\/|feedburner\.com|\/(?:spacer|pixel|blank)\.gif(?:[?#]|$))/i;

  function isBloggerHostedImage(url) {
    return BLOGGER_IMAGE_HOST_RE.test(url || '');
  }

  function looksLikeImageUrl(url) {
    var u = safeHttpUrl(url);
    if (!u) return false;
    if (isBloggerHostedImage(u)) return true;
    return /\.(?:jpe?g|png|webp|gif|avif|bmp|svg)(?:[?#]|$)/i.test(u);
  }

  // Ask Blogger's image server for a large rendition (s1600) of a Blogger-hosted image.
  // Only a recognised size modifier is rewritten; anything unrecognised is returned unchanged.
  // Cards keep the exact original URL as a fallback in case the upgraded URL fails to load.
  function upgradeBloggerImageUrl(url) {
    var u = safeHttpUrl(url);
    if (!u || !isBloggerHostedImage(u)) return u;
    var hashIdx = u.indexOf('#');
    if (hashIdx !== -1) u = u.slice(0, hashIdx);
    var qIdx = u.indexOf('?');
    var query = qIdx !== -1 ? u.slice(qIdx) : '';
    var base = qIdx !== -1 ? u.slice(0, qIdx) : u;
    var lastSlash = base.lastIndexOf('/');
    var eq = base.lastIndexOf('=');
    // Style 1: "=size" suffix (.../img/a/AVvX...=w400-h300, lh*.googleusercontent.com/...=s0)
    if (eq > lastSlash) {
      var params = base.slice(eq + 1);
      if (params === '' || BLOGGER_SIZE_TOKEN_RE.test(params)) return base.slice(0, eq) + '=s1600' + query;
      return u;
    }
    if (/\/img\/a\/[^\/]+$/i.test(base)) return base + '=s1600' + query;
    // Style 2: "/size/" path segment directly before the file name (.../img/b/.../s320/name.png)
    var parts = base.split('/');
    if (parts.length >= 6 && BLOGGER_SIZE_TOKEN_RE.test(parts[parts.length - 2])) {
      parts[parts.length - 2] = 's1600';
      return parts.join('/') + query;
    }
    return u;
  }

  function firstSrcsetUrl(srcset) {
    if (!srcset) return '';
    var first = String(srcset).split(',')[0] || '';
    return first.trim().split(/\s+/)[0] || '';
  }

  // Returns de-duplicated [{ src, fallback }] for real images in post HTML, in document order.
  // src = best rendition (full-size link target, upgraded); fallback = exact URL used in the post.
  function extractImagesFromContent(contentHtml) {
    var results = [];
    var seen = {};
    function add(fullUrl, originalUrl) {
      var original = safeHttpUrl(originalUrl || '') || safeHttpUrl(fullUrl || '');
      var display = upgradeBloggerImageUrl(fullUrl || originalUrl || '');
      if (!display || NON_ARTWORK_IMAGE_RE.test(display) || (original && NON_ARTWORK_IMAGE_RE.test(original))) return;
      var key = display.replace(/^http:/i, 'https:');
      if (seen[key]) return;
      seen[key] = true;
      results.push({ src: display, fallback: (original && original !== display) ? original : '' });
    }
    if (!contentHtml || typeof contentHtml !== 'string') return results;

    var doc = parseHtmlInert(contentHtml);
    if (doc) {
      var imgs = doc.body.querySelectorAll('img');
      for (var i = 0; i < imgs.length; i++) {
        var img = imgs[i];
        var src = img.getAttribute('src') || '';
        if (!src || /^data:/i.test(src)) src = img.getAttribute('data-src') || firstSrcsetUrl(img.getAttribute('srcset')) || '';
        var w = parseInt(img.getAttribute('width') || '0', 10);
        var h = parseInt(img.getAttribute('height') || '0', 10);
        if ((w > 0 && w <= 2) || (h > 0 && h <= 2)) continue; // tracking pixel
        var anchor = img.closest ? img.closest('a[href]') : null;
        var href = anchor ? (anchor.getAttribute('href') || '') : '';
        add(looksLikeImageUrl(href) ? href : '', src);
      }
      return results;
    }

    // Regex fallback for environments without DOMParser HTML support
    var raw = String(contentHtml);
    var aImgRegex = /<a\b[^>]*\bhref=["']([^"']+)["'][^>]*>\s*<img\b[^>]*\bsrc=["']([^"']+)["']/gi;
    var m;
    while ((m = aImgRegex.exec(raw)) !== null) {
      var linkHref = decodeHtmlEntities(m[1]);
