    }
    var imgRegex = /<img\b[^>]*\bsrc=["']([^"']+)["']/gi;
    while ((m = imgRegex.exec(raw)) !== null) {
      add('', decodeHtmlEntities(m[1]));
    }
    return results;
  }

  // ---------------------------------------------------------------------------
  // YouTube cover thumbnails for Reels (vertical 9:16 card, object-fit: cover)
  // ---------------------------------------------------------------------------
  // Best quality first. For a missing size YouTube answers either with an HTTP error ("error"
  // event) or with a 120x90 grey placeholder ("load" event), so both advance to the next size.
  // default.jpg (120x90) is the smallest real thumbnail and is accepted as-is.
  var YT_COVER_SIZES = ['maxresdefault', 'sddefault', 'hqdefault', 'mqdefault', 'default'];

  function youTubeCoverUrl(videoId, step) {
    return 'https://i.ytimg.com/vi/' + encodeURIComponent(videoId) + '/' + YT_COVER_SIZES[step || 0] + '.jpg';
  }

  function advanceReelCover(imgEl) {
    var ytId = imgEl.getAttribute('data-yt-id') || '';
    var step = parseInt(imgEl.getAttribute('data-cover-step') || '0', 10);
    if (isNaN(step) || !isValidYouTubeId(ytId)) step = YT_COVER_SIZES.length;
    var next = step + 1;
    if (next < YT_COVER_SIZES.length) {
      imgEl.setAttribute('data-cover-step', String(next));
      imgEl.src = youTubeCoverUrl(ytId, next);
      return;
    }
    // Every thumbnail size failed: show a neutral "cover unavailable" state, never a fake cover.
    imgEl.onerror = null;
    imgEl.onload = null;
    imgEl.style.display = 'none';
    var wrap = imgEl.closest ? imgEl.closest('.reel-thumbnail-wrap') : imgEl.parentNode;
    if (wrap && wrap.classList) wrap.classList.add('no-cover');
  }

  window.handleReelCoverImgError = function(imgEl) {
    if (imgEl) advanceReelCover(imgEl);
  };

  window.handleReelCoverImgLoad = function(imgEl) {
    if (!imgEl) return;
    var step = parseInt(imgEl.getAttribute('data-cover-step') || '0', 10);
    if (step < YT_COVER_SIZES.length - 1 && imgEl.naturalWidth > 0 && imgEl.naturalWidth <= 120) {
      advanceReelCover(imgEl);
    }
  };

  // Graphics image failure: first retry the exact URL from the post, then show an honest state.
  window.handleGraphicImgError = function(imgEl) {
    if (!imgEl) return;
    var fallback = imgEl.getAttribute('data-fallback-src') || '';
    if (fallback && imgEl.getAttribute('data-fallback-used') !== '1') {
      imgEl.setAttribute('data-fallback-used', '1');
      feedLog('warn', 'Upgraded artwork URL failed to load; using the original post image URL instead.', fallback);
      imgEl.src = fallback;
      return;
    }
    imgEl.onerror = null;
    imgEl.style.display = 'none';
    var wrap = imgEl.closest ? imgEl.closest('.graphic-image-wrap, .lightbox-body') : imgEl.parentNode;
    if (wrap && wrap.classList) wrap.classList.add('img-failed');
    if (wrap && wrap.id === 'lightboxBody' && !wrap.querySelector('.lightbox-img-failed')) {
      var msg = document.createElement('div');
      msg.className = 'lightbox-img-failed';
      msg.style.cssText = 'padding: 40px; text-align: center; color: #FFFFFF;';
      msg.textContent = 'This artwork image could not be loaded.';
      wrap.appendChild(msg);
    }
  };

  function pad2(n) {
    return (n < 10 ? '0' : '') + n;
  }

  function updateReelsCounter() {
    var counterEl = document.getElementById('reelsCounter');
    if (!counterEl) return;
    if (!filteredReels.length) {
      counterEl.innerHTML = (bloggerFeedState.isLoading ? '--' : '00') + ' <span>/ ' + (bloggerFeedState.isLoading ? '--' : '00') + '</span>';
      return;
    }
    counterEl.innerHTML = pad2(activeReelIndex + 1) + ' <span>/ ' + pad2(filteredReels.length) + '</span>';
  }

  function pluralPosts(n) {
    return n + (n === 1 ? ' post' : ' posts');
  }

  // Explains (without exposing anything private) why matching posts are not displayed.
  function buildSkippedPostsNote(section) {
    var notes = bloggerFeedState.notes || {};
    var parts = [];
    if (section === 'reels' && notes.reelsWithoutVideo && notes.reelsWithoutVideo.length) {
      parts.push(pluralPosts(notes.reelsWithoutVideo.length) + " labeled 'Reels' could not be shown because no valid YouTube video link was found.");
    }
    if (notes.conflicts && notes.conflicts.length) {
      parts.push(pluralPosts(notes.conflicts.length) + " labeled both 'Reels' and 'Graphics' " + (notes.conflicts.length === 1 ? 'is' : 'are') + " hidden until one of the two labels is removed.");
    }
    if (!parts.length) return '';
    return "<p class='feed-state-note'>" + escapeHtml(parts.join(' ')) + "</p>";
  }

  // Render Reels Carousel Track
  function renderReelsCarousel() {
    var track = document.getElementById('reelsTrack');
    if (!track) return;

    // Clean up active playback before re-rendering
    cleanupActivePlayer();

    // Loading state (first load, or a retry while nothing is displayed yet)
    if (bloggerFeedState.isLoading && !REELS_DATA.length) {
      track.innerHTML = "<div style='padding: 60px 24px; text-align: center; color: var(--muted); width: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center;'>" +
        "<div class='reel-spinner' style='display: block; margin: 0 auto 16px;'></div>" +
        "<div style='font-size: 0.95rem; font-weight: 500;'>Loading published reels...</div>" +
        "</div>";
      updateReelsCounter();
      return;
    }

    // Error state: the feed could not be retrieved (distinct from a valid empty feed)
    if (bloggerFeedState.reelsError && !REELS_DATA.length) {
      track.innerHTML = "<div style='padding: 50px 24px; text-align: center; color: var(--muted); width: 100%; max-width: 500px; margin: 0 auto;'>" +
        "<svg xmlns='http://www.w3.org/2000/svg' width='40' height='40' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' style='margin: 0 auto 16px; opacity: 0.6;'><circle cx='12' cy='12' r='10'/><line x1='12' y1='8' x2='12' y2='12'/><line x1='12' y1='16' x2='12.01' y2='16'/></svg>" +
        "<div style='font-size: 1.05rem; font-weight: 600; color: var(--text); margin-bottom: 8px;'>Reels Could Not Load</div>" +
        "<p style='font-size: 0.88rem; margin-bottom: 20px;'>" + escapeHtml(bloggerFeedState.reelsErrorMsg || 'Could not load reels right now.') + "</p>" +
        "<button id='reelsRetryBtn' type='button' class='btn btn-primary' style='padding: 8px 20px; font-size: 0.85rem;'>Retry</button>" +
        "</div>";
      var retryBtn = document.getElementById('reelsRetryBtn');
      if (retryBtn) {
        retryBtn.addEventListener('click', function() {
          discoverBloggerPosts();
        });
      }
      updateReelsCounter();
      return;
    }

    if (!filteredReels.length) {
      if (REELS_DATA.length) {
        // Reels exist, but none in the selected category
        track.innerHTML = "<div style='padding: 60px 24px; text-align: center; color: var(--muted); width: 100%; max-width: 480px; margin: 0 auto;'>" +
          "<div style='font-size: 1rem; font-weight: 600; color: var(--text); margin-bottom: 8px;'>No Reels in This Category Yet</div>" +
          "<p style='font-size: 0.88rem;'>Choose <strong>All Reels</strong> to see every published reel.</p>" +
          "</div>";
      } else {
        track.innerHTML = "<div style='padding: 60px 24px; text-align: center; color: var(--muted); width: 100%; max-width: 480px; margin: 0 auto;'>" +
          "<svg xmlns='http://www.w3.org/2000/svg' width='40' height='40' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round' style='margin: 0 auto 16px; opacity: 0.5;'><rect width='18' height='18' x='3' y='3' rx='2' ry='2'/><polyline points='11 3 11 11 14 8 17 11 17 3'/></svg>" +
          "<div style='font-size: 1rem; font-weight: 600; color: var(--text); margin-bottom: 8px;'>No Reels Published Yet</div>" +
          "<p style='font-size: 0.88rem;'>No published reels are available yet.</p>" +
          buildSkippedPostsNote('reels') +
          "</div>";
      }
      updateReelsCounter();
      return;
    }

    if (activeReelIndex >= filteredReels.length) activeReelIndex = 0;
    if (activeReelIndex < 0) activeReelIndex = filteredReels.length - 1;

    var html = '';
    filteredReels.forEach(function(reel, idx) {
      var isActive = idx === activeReelIndex;
      var badgeText = (reel.badge || 'REEL').toUpperCase();
      var altText = reel.title ? (reel.title + ' (YouTube video cover)') : 'Reel video cover';

      html += "<div class='reel-card" + (isActive ? ' active' : '') + "' data-index='" + idx + "' data-id='" + escapeHtml(reel.id) + "'>";
      html += "<div class='reel-frame-inner'>";

      // Cover: real YouTube thumbnail for this video ID, with quality fallbacks (no autoplay)
      html += "<div class='reel-thumbnail-wrap' id='reelThumb-" + idx + "'>";
      html += "<img class='reel-cover-img' src='" + escapeHtml(youTubeCoverUrl(reel.youtubeId, 0)) + "' alt='" + escapeHtml(altText) + "' data-cover-step='0' data-yt-id='" + escapeHtml(reel.youtubeId) + "' onload='window.handleReelCoverImgLoad(this);' onerror='window.handleReelCoverImgError(this);' loading='lazy' decoding='async'/>";
      html += "<span class='reel-cover-missing'>Cover image unavailable</span>";
      html += "<span class='reel-badge-category'>" + escapeHtml(badgeText) + "</span>";
      html += "<div class='reel-play-btn-wrap' data-play-index='" + idx + "' title='Play Reel'>";
      html += "<div class='reel-play-btn'><svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><polygon points='5 3 19 12 5 21 5 3'/></svg></div>";
      html += "</div>";
      html += "<div class='reel-meta-bottom'>";
      if (reel.title) html += "<div class='reel-meta-title'>" + escapeHtml(reel.title) + "</div>";
      if (reel.description) html += "<div class='reel-meta-desc'>" + escapeHtml(reel.description) + "</div>";
      html += "</div></div>";

      // Iframe Container
      html += "<div class='reel-iframe-container' id='reelIframeBox-" + idx + "'></div>";

      // Status Overlay (Loading/Error)
      html += "<div class='reel-status-overlay hidden' id='reelStatus-" + idx + "'>";
      html += "<div class='reel-spinner'></div>";
      html += "<div class='reel-error-text' id='reelErrorText-" + idx + "'>Loading YouTube Player...</div>";
      html += "<button class='reel-retry-btn hidden' id='reelRetry-" + idx + "' type='button'>Retry Playback</button>";
      html += "</div>";

      html += "</div></div>";
    });

    track.innerHTML = html;
    updateReelsCounter();

    // Attach click events to cards & play buttons
    var cardEls = track.querySelectorAll('.reel-card');
    cardEls.forEach(function(cardEl) {
      var idx = parseInt(cardEl.getAttribute('data-index'), 10);

      cardEl.addEventListener('click', function(e) {
        var playBtn = e.target.closest('.reel-play-btn-wrap');
        if (playBtn) {
          if (idx !== activeReelIndex) {
            selectReel(idx, { smooth: true });
          }
          playReel(idx);
        } else {
          selectReel(idx, { smooth: true });
        }
      });
    });
  }

  function selectReel(index, options) {
    if (!filteredReels.length) return;
    if (index < 0) index = 0;
    if (index >= filteredReels.length) index = filteredReels.length - 1;

    var opts = options || {};
    var isSmooth = opts.smooth !== false;

    if (index !== activeReelIndex) {
      cleanupActivePlayer();
      activeReelIndex = index;
    }

    var cards = document.querySelectorAll('#reelsTrack .reel-card');
    cards.forEach(function(card, idx) {
      card.classList.toggle('active', idx === activeReelIndex);
    });

    var counterEl = document.getElementById('reelsCounter');
    if (counterEl) {
      var numStr = (activeReelIndex + 1 < 10 ? '0' : '') + (activeReelIndex + 1);
      var totalStr = (filteredReels.length < 10 ? '0' : '') + filteredReels.length;
      counterEl.innerHTML = numStr + " <span>/ " + totalStr + "</span>";
    }

    // Scroll selected card to exact horizontal center strictly inside the wrapper container
    // Do NOT use targetCard.scrollIntoView() which causes unwanted document-level vertical scrolling!
    var targetCard = cards[activeReelIndex];
    var wrapper = document.getElementById('reelsTrackWrapper');
    if (targetCard && wrapper) {
      var cardOffset = targetCard.offsetLeft + (targetCard.offsetWidth / 2) - (wrapper.clientWidth / 2);
      var targetLeft = Math.max(0, cardOffset);

      if (Math.abs(wrapper.scrollLeft - targetLeft) > 2) {
        isCarouselProgrammaticScroll = true;
        clearTimeout(carouselProgrammaticTimer);
        carouselProgrammaticTimer = setTimeout(function() {
          isCarouselProgrammaticScroll = false;
        }, isSmooth ? 500 : 50);

        if (typeof wrapper.scrollTo === 'function') {
          wrapper.scrollTo({
            left: targetLeft,
            behavior: isSmooth ? 'smooth' : 'auto'
          });
        } else {
          wrapper.scrollLeft = targetLeft;
        }
      }
    }
  }

  function playReel(index, options) {
    var reel = filteredReels[index];
    if (!reel || !reel.youtubeId) return;

    var opts = options || {};
    var isResume = opts.isResume === true;
    var reelId = reel.id;
    var state = getReelPlaybackState(reelId);
    state.index = index;

    // If this Reel is already active and playing, toggle pause (manual user action)
    if (!isResume && activePlayingReelId === reelId && activeYtPlayer) {
      if (typeof activeYtPlayer.getPlayerState === 'function') {
        var currentState = activeYtPlayer.getPlayerState();
        if (window.YT && window.YT.PlayerState) {
          if (currentState === window.YT.PlayerState.PLAYING || currentState === window.YT.PlayerState.BUFFERING) {
            // Manual user pause: clear auto-pause intent so it stays paused when scrolling
            state.wasPlayingBeforeHidden = false;
            state.isAutoPaused = false;
            state.isManuallyPaused = true;
            state.isPlaying = false;
            try {
              activeYtPlayer.pauseVideo();
            } catch (err) {}
            var currentThumb = document.getElementById('reelThumb-' + index);
            if (currentThumb) {
              currentThumb.style.opacity = '1';
              currentThumb.style.pointerEvents = 'auto';
            }
            return;
          } else if (currentState === window.YT.PlayerState.PAUSED) {
            // Manual user resume
            state.wasPlayingBeforeHidden = false;
            state.isAutoPaused = false;
            state.isManuallyPaused = false;
            state.isPlaying = true;
            var currentThumbWrap = document.getElementById('reelThumb-' + index);
            if (currentThumbWrap) {
              currentThumbWrap.style.opacity = '0';
              currentThumbWrap.style.pointerEvents = 'none';
            }
            try {
              activeYtPlayer.playVideo();
            } catch (err) {}
            return;
          }
        }
      }
    }

    // If starting a different reel or starting fresh, cleanup any other playing reel
    if (activePlayingReelId && activePlayingReelId !== reelId) {
      var prevReelState = getReelPlaybackState(activePlayingReelId);
      prevReelState.isPlaying = false;
      prevReelState.wasPlayingBeforeHidden = false;
      prevReelState.isAutoPaused = false;
      prevReelState.isManuallyPaused = false;
      prevReelState.resumePending = false;
      prevReelState.isReady = false;
      prevReelState.player = null;
      cleanupActivePlayer({ preserveState: false });
    }

    // Set as currently intended playing reel
    activePlayingReelId = reelId;
    state.isManuallyPaused = false;
    state.isPlaying = true;
    if (!isResume) {
      state.wasPlayingBeforeHidden = false;
      state.isAutoPaused = false;
    }

    var iframeBox = document.getElementById('reelIframeBox-' + index);
    var thumbWrap = document.getElementById('reelThumb-' + index);
    var statusOverlay = document.getElementById('reelStatus-' + index);
    var errorText = document.getElementById('reelErrorText-' + index);
    var retryBtn = document.getElementById('reelRetry-' + index);

    if (!iframeBox) return;

    // If player instance already exists and is ready, resume without reloading iframe
    if (activeYtPlayer && state.containerId === 'ytPlayerInstance-' + index && state.isReady) {
      if (thumbWrap) {
        thumbWrap.style.opacity = '0';
        thumbWrap.style.pointerEvents = 'none';
      }
      try {
        if (isMuted && typeof activeYtPlayer.mute === 'function') activeYtPlayer.mute();
        activeYtPlayer.playVideo();
      } catch (err) {
        if (statusOverlay) {
          statusOverlay.classList.remove('hidden');
          if (errorText) errorText.textContent = "Unable to resume playback. Tap play button to start.";
        }
      }
      return;
    }

    // Show loading overlay
    if (statusOverlay) {
      statusOverlay.classList.remove('hidden');
      if (errorText) errorText.textContent = "Connecting to YouTube...";
      if (retryBtn) retryBtn.classList.add('hidden');
    }

    state.resumePending = true;

    loadYouTubeIframeApi(function() {
      // If another reel was clicked while loading, abort
      if (activePlayingReelId !== reelId || activeReelIndex !== index) {
        state.resumePending = false;
        return;
      }

      cleanupActivePlayer({ preserveState: true });
      activePlayingReelId = reelId;

      var containerId = 'ytPlayerInstance-' + index;
      state.containerId = containerId;
      iframeBox.innerHTML = "<div id='" + containerId + "'></div>";

      if (statusOverlay) statusOverlay.classList.add('hidden');

      try {
        var pVars = Object.assign({}, STUDIO_CONFIG.youtubePlayerVars, {
          mute: isMuted ? 1 : 0
        });

        activeYtPlayer = new window.YT.Player(containerId, {
          height: '100%',
          width: '100%',
          videoId: reel.youtubeId,
          playerVars: pVars,
          events: {
            onReady: function(event) {
              state.isReady = true;
              state.resumePending = false;
              state.player = event.target;
              activeYtIframeId = containerId;

              // Ensure this is still the active reel before playing
              if (activePlayingReelId === reelId) {
                if (thumbWrap) {
                  thumbWrap.style.opacity = '0';
                  thumbWrap.style.pointerEvents = 'none';
                }
                try {
                  event.target.playVideo();
                } catch (playErr) {
                  // Browser autoplay restriction handling
                  if (statusOverlay) {
                    statusOverlay.classList.remove('hidden');
                    if (errorText) errorText.textContent = "Autoplay restricted. Tap play to view.";
                  }
                }
              }
            },
            onStateChange: function(event) {
              if (!window.YT || !window.YT.PlayerState) return;

              if (event.data === window.YT.PlayerState.PLAYING) {
                state.isPlaying = true;
                state.isManuallyPaused = false;
                state.isAutoPaused = false;
                if (thumbWrap) {
                  thumbWrap.style.opacity = '0';
                  thumbWrap.style.pointerEvents = 'none';
                }
              } else if (event.data === window.YT.PlayerState.PAUSED) {
                state.isPlaying = false;
                // If this pause was not triggered automatically by scrolling, mark as manual pause
                if (!isAutoPausingOrResuming) {
                  state.isManuallyPaused = true;
                  state.wasPlayingBeforeHidden = false;
                  state.isAutoPaused = false;
                  if (thumbWrap) {
                    thumbWrap.style.opacity = '1';
                    thumbWrap.style.pointerEvents = 'auto';
                  }
                }
              } else if (event.data === window.YT.PlayerState.ENDED) {
                // When finished, do not loop or start next reel
                state.isPlaying = false;
                state.wasPlayingBeforeHidden = false;
                state.isAutoPaused = false;
                state.isManuallyPaused = false;
                state.resumePending = false;
                cleanupActivePlayer({ preserveState: false });
              }
            },
            onError: function(e) {
              state.isPlaying = false;
              state.resumePending = false;
              if (statusOverlay) {
                statusOverlay.classList.remove('hidden');
                var msg = "Video unavailable or embedding restricted.";
                if (e && e.data === 150) msg = "Playback restricted by video owner.";
                if (errorText) errorText.textContent = msg;
                if (retryBtn) {
                  retryBtn.classList.remove('hidden');
                  retryBtn.onclick = function() {
                    playReel(index);
                  };
                }
              }
            }
          }
        });
      } catch (err) {
        state.resumePending = false;
        if (statusOverlay) {
          statusOverlay.classList.remove('hidden');
          if (errorText) errorText.textContent = "Unable to initialize YouTube API player.";
        }
      }
    });
  }

  // Setup Reels Controls & Touch Gestures
  function setupReelsControls() {
    var prevBtn = document.getElementById('reelPrevBtn');
    var nextBtn = document.getElementById('reelNextBtn');
    var muteBtn = document.getElementById('reelMuteBtn');
    var muteIcon = document.getElementById('reelMuteIcon');
    var filterBtns = document.querySelectorAll('#reelsFilterGroup .reel-filter-btn');

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        if (!filteredReels.length) return;
        var newIdx = (activeReelIndex - 1 + filteredReels.length) % filteredReels.length;
        selectReel(newIdx);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        if (!filteredReels.length) return;
        var newIdx = (activeReelIndex + 1) % filteredReels.length;
        selectReel(newIdx);
      });
    }

    // Keep the mute button icon/title in sync with the real state (the static markup shows the
    // "muted" icon while sound is actually on, so the first click appeared to do nothing).
    function syncMuteUi() {
      if (muteBtn) {
        muteBtn.setAttribute('title', isMuted ? 'Unmute' : 'Mute');
        muteBtn.setAttribute('aria-pressed', isMuted ? 'true' : 'false');
      }
      if (muteIcon) {
        muteIcon.innerHTML = isMuted ?
          "<polygon points='11 5 6 9 2 9 2 15 6 15 11 19 11 5'/><line x1='23' x2='17' y1='9' y2='15'/><line x1='17' x2='23' y1='9' y2='15'/>" :
          "<polygon points='11 5 6 9 2 9 2 15 6 15 11 19 11 5'/><path d='M15.54 8.46a5 5 0 0 1 0 7.07'/><path d='M19.07 4.93a10 10 0 0 1 0 14.14'/>";
      }
    }

    if (muteBtn) {
      syncMuteUi();
      muteBtn.addEventListener('click', function() {
        isMuted = !isMuted;
        if (activeYtPlayer && typeof activeYtPlayer.mute === 'function') {
          if (isMuted) activeYtPlayer.mute();
          else activeYtPlayer.unMute();
        }
        syncMuteUi();
      });
    }

    filterBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        filterBtns.forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');
        applyReelFilter();
        activeReelIndex = 0;
        renderReelsCarousel();
      });
    });

    // Touch gestures & Scroll listener for carousel centering & active index synchronization
    var reelsTrackWrapper = document.getElementById('reelsTrackWrapper');
    if (reelsTrackWrapper) {
      var scrollDebounceTimer = null;
      var lastWrapperWidth = reelsTrackWrapper.clientWidth;

      reelsTrackWrapper.addEventListener('scroll', function() {
        if (isCarouselProgrammaticScroll) return;

        clearTimeout(scrollDebounceTimer);
        scrollDebounceTimer = setTimeout(function() {
          if (isCarouselProgrammaticScroll) return;

          var cards = reelsTrackWrapper.querySelectorAll('.reel-card');
          var wrapperCenter = reelsTrackWrapper.scrollLeft + (reelsTrackWrapper.clientWidth / 2);
          var closestIdx = activeReelIndex;
          var minDistance = Infinity;

          cards.forEach(function(card) {
            var idx = parseInt(card.getAttribute('data-index'), 10);
            var cardCenter = card.offsetLeft + (card.offsetWidth / 2);
            var dist = Math.abs(wrapperCenter - cardCenter);
            if (dist < minDistance) {
              minDistance = dist;
              closestIdx = idx;
            }
          });

          if (closestIdx !== activeReelIndex && !isNaN(closestIdx)) {
            cleanupActivePlayer();
            activeReelIndex = closestIdx;
            cards.forEach(function(card, idx) {
              card.classList.toggle('active', idx === activeReelIndex);
            });
            var counterEl = document.getElementById('reelsCounter');
            if (counterEl) {
              var numStr = (activeReelIndex + 1 < 10 ? '0' : '') + (activeReelIndex + 1);
              var totalStr = (filteredReels.length < 10 ? '0' : '') + filteredReels.length;
              counterEl.innerHTML = numStr + " <span>/ " + totalStr + "</span>";
            }
          }
        }, 60);
      }, { passive: true });

      // Only re-center horizontally if width actually changed (prevents vertical mobile address-bar resize jumps)
      window.addEventListener('resize', function() {
        var newWidth = reelsTrackWrapper.clientWidth;
        if (Math.abs(newWidth - lastWrapperWidth) > 10) {
          lastWrapperWidth = newWidth;
          selectReel(activeReelIndex, { smooth: false });
        }
      }, { passive: true });
    }

    // Initialize IntersectionObserver and visibility listeners for Smart Auto-Pause & Resume
    initReelsVisibilityObserver();
  }

  // Smart Reel Visibility Management (IntersectionObserver & Page Visibility)
  function initReelsVisibilityObserver() {
    var reelsSection = document.getElementById('reels');
    var reelsContainer = document.getElementById('reelsContainer') || document.getElementById('reelsTrackWrapper');
    if (!reelsContainer && !reelsSection) return;

    if (reelsIntersectionObserver) {
      try { reelsIntersectionObserver.disconnect(); } catch (e) {}
      reelsIntersectionObserver = null;
    }

    // Helper to pause active playing reel automatically due to visibility change
    function handleAutoPause() {
      if (!activePlayingReelId) return;
      var state = getReelPlaybackState(activePlayingReelId);

      // Check if player is currently playing or buffering
      var isCurrentlyPlaying = state.isPlaying;
      if (activeYtPlayer && typeof activeYtPlayer.getPlayerState === 'function') {
        try {
          var pState = activeYtPlayer.getPlayerState();
          if (window.YT && window.YT.PlayerState) {
            if (pState === window.YT.PlayerState.PLAYING || pState === window.YT.PlayerState.BUFFERING) {
              isCurrentlyPlaying = true;
            } else if (pState === window.YT.PlayerState.PAUSED) {
              isCurrentlyPlaying = false;
            }
          }
        } catch (e) {}
      }

      if (isCurrentlyPlaying && !state.isManuallyPaused) {
        state.wasPlayingBeforeHidden = true;
        state.isAutoPaused = true;
        state.isPlaying = false;
        isAutoPausingOrResuming = true;
        try {
          if (activeYtPlayer && typeof activeYtPlayer.pauseVideo === 'function') {
            activeYtPlayer.pauseVideo();
          }
        } catch (e) {}
        setTimeout(function() {
          isAutoPausingOrResuming = false;
        }, 50);
      }
    }

    // Helper to resume active playing reel automatically when visible again
    function handleAutoResume() {
      if (!activePlayingReelId) return;
      var state = getReelPlaybackState(activePlayingReelId);

      // Resume only if it was playing before becoming hidden and was not manually paused
      if (state.wasPlayingBeforeHidden && state.isAutoPaused && !state.isManuallyPaused) {
        state.wasPlayingBeforeHidden = false;
        state.isAutoPaused = false;
        state.isPlaying = true;
        isAutoPausingOrResuming = true;

        if (state.index >= 0 && state.index === activeReelIndex) {
          playReel(state.index, { isResume: true });
        }

        setTimeout(function() {
          isAutoPausingOrResuming = false;
        }, 50);
      }
    }

    // Setup IntersectionObserver if supported
    if ('IntersectionObserver' in window) {
      // Sensible threshold with hysteresis: pause below 0.35, resume above 0.5
      var targetElement = reelsContainer || reelsSection;
      try {
        reelsIntersectionObserver = new IntersectionObserver(function(entries) {
          entries.forEach(function(entry) {
            if (entry.isIntersecting && entry.intersectionRatio >= 0.5) {
              handleAutoResume();
            } else if (!entry.isIntersecting || entry.intersectionRatio < 0.35) {
              handleAutoPause();
            }
          });
        }, {
          root: null,
          threshold: [0, 0.25, 0.35, 0.5, 0.75, 1.0]
        });

        reelsIntersectionObserver.observe(targetElement);
      } catch (err) {}
    }

    // Document Visibility Change (Tab Blur / Minimization)
    document.addEventListener('visibilitychange', function() {
      if (document.hidden) {
        handleAutoPause();
      } else {
        // Tab restored: check if reel container is currently visible in viewport
        var isVisible = true;
        var el = reelsContainer || reelsSection;
        if (el && typeof el.getBoundingClientRect === 'function') {
          var rect = el.getBoundingClientRect();
          var windowHeight = window.innerHeight || document.documentElement.clientHeight;
          // Sufficiently visible if at least 35% of element is in view or crosses viewport center
          var visibleHeight = Math.max(0, Math.min(rect.bottom, windowHeight) - Math.max(rect.top, 0));
          var ratio = rect.height > 0 ? (visibleHeight / rect.height) : 0;
          isVisible = ratio >= 0.35;
        }

        if (isVisible) {
          handleAutoResume();
        }
      }
    });

    // Window Blur/Focus fallback for older browsers or app webviews
    window.addEventListener('blur', function() {
      // Tapping/clicking inside the YouTube player moves focus into its iframe, which blurs this
      // window. That is the visitor using the Reel (e.g. unmute, seek), not leaving the page, so
      // it must not auto-pause. Tab switches are still handled by the visibilitychange listener.
      setTimeout(function() {
        var focused = document.activeElement;
        if (focused && focused.tagName === 'IFRAME' && focused.closest && focused.closest('#reelsTrack')) return;
        handleAutoPause();
      }, 0);
    });
    window.addEventListener('focus', function() {
      var isVisible = true;
      var el = reelsContainer || reelsSection;
      if (el && typeof el.getBoundingClientRect === 'function') {
        var rect = el.getBoundingClientRect();
        var windowHeight = window.innerHeight || document.documentElement.clientHeight;
        var visibleHeight = Math.max(0, Math.min(rect.bottom, windowHeight) - Math.max(rect.top, 0));
        var ratio = rect.height > 0 ? (visibleHeight / rect.height) : 0;
        isVisible = ratio >= 0.35;
      }
      if (isVisible) {
        handleAutoResume();
      }
    });
  }

  // Render Graphic Design Gallery & Lightbox Modal
  var currentGfxIndex = 0;
  var filteredGraphics = GRAPHICS_DATA.slice();
  var savedLightboxScrollY = 0;
  var lastTriggeringGfxElement = null;

  function getActiveFilterValue(selector, attrName) {
    var btn = document.querySelector(selector);
    return btn ? (btn.getAttribute(attrName) || 'all') : 'all';
  }

  // Re-apply the currently selected filter chip (used after filtering AND after feed refreshes)
  function applyReelFilter() {
    var category = getActiveFilterValue('#reelsFilterGroup .reel-filter-btn.active', 'data-reel-filter');
    filteredReels = category === 'all' ? REELS_DATA.slice() : REELS_DATA.filter(function(r) { return r.category === category; });
  }

  function applyGraphicsFilter() {
    var category = getActiveFilterValue('#graphicsFilterGroup .filter.active', 'data-gfx-filter');
    filteredGraphics = category === 'all' ? GRAPHICS_DATA.slice() : GRAPHICS_DATA.filter(function(g) { return g.category === category; });
  }

  function renderGraphicsGrid() {
    var grid = document.getElementById('graphicsGrid');
    if (!grid) return;

    // Loading state (first load, or a retry while nothing is displayed yet)
    if (bloggerFeedState.isLoading && !GRAPHICS_DATA.length) {
      grid.innerHTML = "<div style='grid-column: 1 / -1; padding: 60px 24px; text-align: center; background: var(--card); border: 1px dashed var(--border); border-radius: 20px; color: var(--muted);'>" +
        "<div class='reel-spinner' style='display: block; margin: 0 auto 16px;'></div>" +
        "<div style='font-size: 0.95rem; font-weight: 500;'>Loading published graphics...</div>" +
        "</div>";
      return;
    }

    // Error state: the feed could not be retrieved (distinct from a valid empty feed)
    if (bloggerFeedState.graphicsError && !GRAPHICS_DATA.length) {
      grid.innerHTML = "<div style='grid-column: 1 / -1; padding: 50px 24px; text-align: center; background: var(--card); border: 1px dashed var(--border); border-radius: 20px; color: var(--muted);'>" +
        "<svg xmlns='http://www.w3.org/2000/svg' width='40' height='40' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' style='margin: 0 auto 16px; opacity: 0.6;'><circle cx='12' cy='12' r='10'/><line x1='12' y1='8' x2='12' y2='12'/><line x1='12' y1='16' x2='12.01' y2='16'/></svg>" +
        "<h3 style='font-family: var(--font-heading); font-size: 1.1rem; color: var(--text); margin-bottom: 8px;'>Graphics Could Not Load</h3>" +
        "<p style='font-size: 0.88rem; max-width: 460px; margin: 0 auto 20px;'>" + escapeHtml(bloggerFeedState.graphicsErrorMsg || 'Could not load graphics right now.') + "</p>" +
        "<button id='graphicsRetryBtn' type='button' class='btn btn-primary' style='padding: 8px 20px; font-size: 0.85rem;'>Retry</button>" +
        "</div>";
      var retryGfxBtn = document.getElementById('graphicsRetryBtn');
      if (retryGfxBtn) {
        retryGfxBtn.addEventListener('click', function() {
          discoverBloggerPosts();
        });
      }
      return;
    }

    if (!filteredGraphics.length) {
      if (GRAPHICS_DATA.length) {
        // Graphics exist, but none in the selected category
        grid.innerHTML = "<div style='grid-column: 1 / -1; padding: 48px 24px; text-align: center; background: var(--card); border: 1px dashed var(--border); border-radius: 20px; color: var(--muted);'>" +
          "<h3 style='font-family: var(--font-heading); font-size: 1.1rem; color: var(--text); margin-bottom: 8px;'>No Graphics in This Category Yet</h3>" +
          "<p style='font-size: 0.88rem; max-width: 460px; margin: 0 auto;'>Choose <strong>All Graphics</strong> to see every published design.</p>" +
          "</div>";
      } else {
        grid.innerHTML = "<div style='grid-column: 1 / -1; padding: 48px 24px; text-align: center; background: var(--card); border: 1px dashed var(--border); border-radius: 20px; color: var(--muted);'>" +
          "<svg xmlns='http://www.w3.org/2000/svg' width='48' height='48' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round' style='margin: 0 auto 16px; display: block; opacity: 0.5;'><rect width='18' height='18' x='3' y='3' rx='2' ry='2'/><circle cx='9' cy='9' r='2'/><path d='m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21'/></svg>" +
          "<h3 style='font-family: var(--font-heading); font-size: 1.1rem; color: var(--text); margin-bottom: 8px;'>No Graphic Projects Found</h3>" +
          "<p style='font-size: 0.88rem; max-width: 460px; margin: 0 auto;'>No published graphics are available yet.</p>" +
          buildSkippedPostsNote('graphics') +
          "</div>";
      }
      return;
    }

    var html = '';
    filteredGraphics.forEach(function(gfx, idx) {
      var hasImage = !!gfx.image;
      var label = gfx.title || 'Graphics artwork';
      html += "<article class='graphic-card" + (hasImage ? '' : ' graphic-card--no-image') + "' data-gfx-index='" + idx + "'" +
        (gfx.postUrl ? " data-post-url='" + escapeHtml(gfx.postUrl) + "'" : '') +
        (hasImage ? " tabindex='0' role='button' aria-label='" + escapeHtml('View artwork: ' + label) + "'" : '') + ">";
      html += "<div class='graphic-image-wrap'>";
      html += "<span class='graphic-badge'>" + escapeHtml(gfx.badge || 'GRAPHICS') + "</span>";
      if (hasImage) {
        html += "<img src='" + escapeHtml(gfx.image) + "'" +
          (gfx.imageFallback ? " data-fallback-src='" + escapeHtml(gfx.imageFallback) + "'" : '') +
          " alt='" + escapeHtml(label) + "' loading='lazy' decoding='async' onerror='window.handleGraphicImgError(this);'/>";
        html += "<span class='graphic-img-failed-msg'>This artwork image could not be loaded.</span>";
      } else {
        html += "<div class='graphic-missing'>" +
          "<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'><rect width='18' height='18' x='3' y='3' rx='2' ry='2'/><line x1='3' y1='3' x2='21' y2='21'/></svg>" +
          "<span>No artwork image found in this Blogger post</span></div>";
      }
      html += "</div>";
      html += "<div class='graphic-info'>";
      if (gfx.title) html += "<h3>" + escapeHtml(gfx.title) + "</h3>";
      html += "<p>" + escapeHtml(gfx.categoryLabel || 'Graphics') + "</p>";
      if (!hasImage && gfx.postUrl) {
        html += "<a class='graphic-post-link' href='" + escapeHtml(gfx.postUrl) + "' target='_blank' rel='noopener noreferrer'>Open post</a>";
      }
      html += "</div></article>";
    });

    grid.innerHTML = html;

    var cards = grid.querySelectorAll('.graphic-card');
    cards.forEach(function(card) {
      var idx = parseInt(card.getAttribute('data-gfx-index'), 10);
      if (card.classList.contains('graphic-card--no-image')) return; // nothing to enlarge
      card.addEventListener('click', function() {
        openLightbox(idx, card);
      });
      card.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openLightbox(idx, card);
        }
      });
    });
  }

  function openLightbox(index, triggerEl) {
    if (index < 0 || index >= filteredGraphics.length) return;
    var gfx = filteredGraphics[index];
    if (!gfx || !gfx.image) return;
    currentGfxIndex = index;

    var modal = document.getElementById('lightboxModal');
    var body = document.getElementById('lightboxBody');
    var titleEl = document.getElementById('lightboxTitle');
    var catEl = document.getElementById('lightboxCat');
    var postLink = document.getElementById('lightboxPostLink');

    if (!modal || !body) return;

    if (triggerEl) {
      lastTriggeringGfxElement = triggerEl;
    } else {
      lastTriggeringGfxElement = document.querySelector('.graphic-card[data-gfx-index="' + index + '"]');
    }

    // Build with DOM APIs (no HTML string interpolation of feed data)
    body.innerHTML = '';
    body.classList.remove('img-failed');
    var img = document.createElement('img');
    img.alt = gfx.title || 'Graphics artwork';
    if (gfx.imageFallback) img.setAttribute('data-fallback-src', gfx.imageFallback);
    img.onerror = function() { window.handleGraphicImgError(img); };
    img.src = gfx.image;
    body.appendChild(img);

    if (titleEl) titleEl.textContent = gfx.title || '';
    if (catEl) catEl.textContent = gfx.categoryLabel || 'Graphics';
    if (postLink) {
      if (gfx.postUrl) {
        postLink.setAttribute('href', gfx.postUrl);
        postLink.hidden = false;
      } else {
        postLink.setAttribute('href', '#graphics');
        postLink.hidden = true;
      }
    }

    if (!modal.classList.contains('open')) {
      savedLightboxScrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
      modal.classList.add('open');
      modal.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }
  }

  // Move to the previous/next artwork that actually has an image
  function stepLightbox(direction) {
    var n = filteredGraphics.length;
    if (!n) return;
    for (var k = 1; k <= n; k++) {
      var i = (((currentGfxIndex + direction * k) % n) + n) % n;
      if (filteredGraphics[i] && filteredGraphics[i].image) {
        openLightbox(i);
        return;
      }
    }
  }

  function closeLightbox() {
    var modal = document.getElementById('lightboxModal');
    if (!modal || !modal.classList.contains('open')) return;

    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';

    // Restore exact document scroll position without jumping
    if (typeof window.scrollTo === 'function') {
      window.scrollTo(0, savedLightboxScrollY);
    }

    // Restore focus to the card that opened the lightbox
    if (lastTriggeringGfxElement && typeof lastTriggeringGfxElement.focus === 'function') {
      try { lastTriggeringGfxElement.focus(); } catch (e) {}
    }
  }

  function setupGraphicsControls() {
    var filterBtns = document.querySelectorAll('#graphicsFilterGroup .filter');
    var closeBtn = document.getElementById('lightboxClose');
    var prevBtn = document.getElementById('lightboxPrev');
    var nextBtn = document.getElementById('lightboxNext');
    var modal = document.getElementById('lightboxModal');

    filterBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        filterBtns.forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');
        applyGraphicsFilter();
        renderGraphicsGrid();
      });
    });

    if (closeBtn) closeBtn.addEventListener('click', closeLightbox);

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        stepLightbox(-1);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        stepLightbox(1);
      });
    }

    if (modal) {
      modal.addEventListener('click', function(e) {
        if (e.target === modal) closeLightbox();
      });
    }

    // Keyboard controls
    document.addEventListener('keydown', function(e) {
      if (modal && modal.classList.contains('open')) {
        if (e.key === 'Escape') closeLightbox();
        else if (e.key === 'ArrowLeft' && prevBtn) prevBtn.click();
        else if (e.key === 'ArrowRight' && nextBtn) nextBtn.click();
      } else if (document.activeElement && document.activeElement.closest && document.activeElement.closest('#reelsContainer')) {
        if (e.key === 'ArrowLeft') {
          var rPrev = document.getElementById('reelPrevBtn');
          if (rPrev) rPrev.click();
        } else if (e.key === 'ArrowRight') {
          var rNext = document.getElementById('reelNextBtn');
          if (rNext) rNext.click();
        }
      }
    });
  }

  /* ==========================================================================
     BLOGGER FEED: endpoint discovery, bounded pagination, strict classification
     ========================================================================== */

  // Where to read THIS blog's feed from, in order of preference:
  //  1. Same-origin JSON  (<page origin>/feeds/posts/default?alt=json). The theme is served by the
  //     blog itself, so this is a same-origin request: no CORS involved.
  //  2. JSONP on the blog's own address (data:blog.homepageUrl). Blogger's feed endpoint supports
  //     alt=json-in-script&callback=fn and answers "fn({...});" (verified against a live
  //     blogspot.com feed), so this works where fetch is unavailable or blocked.
  //  3. JSONP on https://www.blogger.com/feeds/<blogId>/posts/default (same verified format). Covers
  //     Blogger previews and custom feed redirects.
  // No unrelated blog domain is ever used as a fallback.
  function getBlogMeta() {
    var el = document.getElementById('scsBlogMeta');
    return {
      homeUrl: el ? String(el.getAttribute('data-home-url') || '').trim() : '',
      blogId: el ? String(el.getAttribute('data-blog-id') || '').trim() : ''
    };
  }

  function getBloggerFeedEndpoints() {
    var feedPath = STUDIO_CONFIG.bloggerFeed.feedPath || '/feeds/posts/default';
    var meta = getBlogMeta();
    var loc = window.location;
    var isHttp = loc.protocol === 'http:' || loc.protocol === 'https:';
    var servedByBlog = isHttp && !/(^|\.)blogger\.com$/i.test(loc.hostname || '');
    var homeOrigin = '';
    var originMatch = /^(https?:\/\/[^\/?#\s]+)/i.exec(meta.homeUrl);
    if (originMatch) {
      homeOrigin = originMatch[1];
      // Never downgrade to http:// from an https page (mixed content); blogspot serves https.
      if (loc.protocol === 'https:') homeOrigin = homeOrigin.replace(/^http:/i, 'https:');
    }
    var list = [];
    function add(transport, base, name) {
      for (var i = 0; i < list.length; i++) {
        if (list[i].transport === transport && list[i].base.toLowerCase() === base.toLowerCase()) return;
      }
      list.push({ transport: transport, base: base, name: name });
    }
    // Prefer the canonical homepage URL emitted by Blogger, then try the current origin.
    // Custom-domain feed routes can return a valid but empty/unrelated feed response.
    if (homeOrigin) add('jsonp', homeOrigin + feedPath, 'canonical blog JSONP feed');
    if (servedByBlog) add('fetch', loc.origin + feedPath, 'same-origin JSON feed');
    if (!homeOrigin && servedByBlog) add('jsonp', loc.origin + feedPath, 'same-origin JSONP feed');
    if (/^\d+$/.test(meta.blogId)) add('jsonp', 'https://www.blogger.com/feeds/' + meta.blogId + '/posts/default', 'blog-ID JSONP feed');
    return list;
  }

  function buildFeedQuery(alt, startIndex, maxResults) {
    return '?alt=' + alt + '&start-index=' + encodeURIComponent(String(startIndex)) + '&max-results=' + encodeURIComponent(String(maxResults));
  }

  function requestFeedJson(base, startIndex, maxResults, timeoutMs) {
    return new Promise(function(resolve, reject) {
      if (typeof fetch !== 'function') {
        reject(new Error('fetch() is not available in this browser'));
        return;
      }
      var controller = (typeof AbortController === 'function') ? new AbortController() : null;
      var settled = false;
      var timer = setTimeout(function() {
        if (settled) return;
        settled = true;
        if (controller) { try { controller.abort(); } catch (e) {} }
        reject(new Error('timed out after ' + Math.round(timeoutMs / 1000) + 's'));
      }, timeoutMs);
      var init = { method: 'GET', credentials: 'same-origin' };
      if (controller) init.signal = controller.signal;
      fetch(base + buildFeedQuery('json', startIndex, maxResults), init)
        .then(function(res) {
          if (!res.ok) throw new Error('HTTP ' + res.status);
          return res.text();
        })
        .then(function(text) {
          var data;
          try {
            data = JSON.parse(text);
          } catch (parseErr) {
            throw new Error('response was not JSON (is the blog feed disabled or redirected?)');
          }
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve(data);
        })
        .catch(function(err) {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          reject(err instanceof Error ? err : new Error(String(err)));
        });
    });
  }

  var jsonpRequestCounter = 0;
  function requestFeedJsonp(base, startIndex, maxResults, timeoutMs) {
    return new Promise(function(resolve, reject) {
      var callbackName = '__scsFeedCb_' + Date.now() + '_' + (++jsonpRequestCounter);
      var script = document.createElement('script');
      var settled = false;
      var timer = setTimeout(function() {
        finish(new Error('timed out after ' + Math.round(timeoutMs / 1000) + 's'));
      }, timeoutMs);
      function finish(err, data) {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        // Leave a no-op behind so a late response cannot throw a ReferenceError, then clean up.
        window[callbackName] = function() {};
        setTimeout(function() {
          try { delete window[callbackName]; } catch (e) { window[callbackName] = undefined; }
        }, 60000);
        if (script.parentNode) script.parentNode.removeChild(script);
        if (err) reject(err);
        else resolve(data);
      }
      window[callbackName] = function(data) {
        finish(null, data);
      };
      script.onerror = function() {
        finish(new Error('script request failed (network error, HTTP error or blocked)'));
      };
      script.async = true;
      script.src = base + buildFeedQuery('json-in-script', startIndex, maxResults) + '&callback=' + callbackName;
      (document.head || document.body || document.documentElement).appendChild(script);
    });
  }

  function requestFeedPage(endpoint, startIndex, maxResults) {
    var timeoutMs = Math.max(2000, parseInt(STUDIO_CONFIG.bloggerFeed.requestTimeoutMs, 10) || 10000);
    var request = endpoint.transport === 'jsonp'
      ? requestFeedJsonp(endpoint.base, startIndex, maxResults, timeoutMs)
      : requestFeedJson(endpoint.base, startIndex, maxResults, timeoutMs);
    return request.then(function(data) {
      if (!data || typeof data !== 'object' || !data.feed || typeof data.feed !== 'object') {
        throw new Error('response is not a Blogger feed');
      }
      return data;
    });
  }

  // --- Entry field helpers (every field is optional in practice) ---------------
  function feedText(node) {
    if (node && typeof node.$t === 'string') return node.$t;
    if (node && typeof node.$t === 'number') return String(node.$t);
    return '';
  }

  function getEntryPostUrl(entry) {
    var links = entry && entry.link;
    if (!Array.isArray(links)) return '';
    for (var i = 0; i < links.length; i++) {
      if (links[i] && links[i].rel === 'alternate' && links[i].href) return safeHttpUrl(String(links[i].href));
    }
    return '';
  }

  function getEntryKey(entry) {
    var id = feedText(entry.id);
    if (id) return 'id:' + id;
    var url = getEntryPostUrl(entry);
    if (url) return 'url:' + url;
    return 'tp:' + feedText(entry.title) + '|' + feedText(entry.published);
  }

  function getEntryPostId(entry) {
    var id = feedText(entry.id);
    var m = /post-(\d+)/.exec(id);
    if (m) return m[1];
    var key = getEntryKey(entry);
    var hash = 0;
    for (var i = 0; i < key.length; i++) hash = ((hash << 5) - hash + key.charCodeAt(i)) | 0;
    return 'h' + Math.abs(hash);
  }

  function normalizeLabel(value) {
    return String(value === null || value === undefined ? '' : value).replace(/\s+/g, ' ').trim().toLowerCase();
  }

  function getEntryLabels(entry) {
    var cats = entry.category;
    if (!cats) return [];
    if (!Array.isArray(cats)) cats = [cats];
    var labels = [];
    cats.forEach(function(cat) {
      var term = normalizeLabel(cat && typeof cat === 'object' ? cat.term : cat);
      if (term && labels.indexOf(term) === -1) labels.push(term);
    });
    return labels;
  }

  // Optional extra labels -> filter chip inside a section (exact, case-insensitive label match)
  var GRAPHICS_SUBLABELS = [
    { category: 'logo', badge: 'LOGO', label: 'Logo Design', terms: ['logo design', 'logo', 'logos'] },
    { category: 'social', badge: 'SOCIAL', label: 'Social Media Post', terms: ['social media posts', 'social media post', 'social media', 'social'] },
    { category: 'thumbnail', badge: 'THUMBNAIL', label: 'YouTube Thumbnail', terms: ['youtube thumbnails', 'youtube thumbnail', 'thumbnails', 'thumbnail'] },
    { category: 'poster', badge: 'POSTER', label: 'Poster & Banner', terms: ['posters & banners', 'posters and banners', 'posters', 'poster', 'banners', 'banner'] },
    { category: 'ads', badge: 'AD CREATIVE', label: 'Advertising Creative', terms: ['advertising creatives', 'advertising creative', 'advertising', 'ads', 'ad creative'] },
    { category: 'brand', badge: 'BRANDING', label: 'Visual Branding', terms: ['brand identity', 'branding', 'brand'] }
  ];

  var REELS_SUBLABELS = [
    { category: '2d', badge: '2D', terms: ['2d animation', '2d'] },
    { category: '3d', badge: '3D', terms: ['3d animation', '3d'] },
    { category: 'editing', badge: 'EDITING', terms: ['video editing', 'editing'] },
    { category: 'ai-ads', badge: 'AI ADS', terms: ['ai product ads', 'ai product ad', 'ai ads', 'ai-ads'] },
    { category: 'motion', badge: 'MOTION', terms: ['motion graphics', 'motion design', 'motion'] }
  ];

  function matchSublabel(labels, table) {
    for (var i = 0; i < table.length; i++) {
      for (var j = 0; j < table[i].terms.length; j++) {
        if (labels.indexOf(table[i].terms[j]) !== -1) return table[i];
      }
    }
    return null;
  }

  function buildExcerpt(html, title) {
    var text = htmlToPlainText(html);
    if (!text || text === title) return '';
    return text.length > 120 ? text.slice(0, 117).replace(/\s+\S*$/, '') + '\u2026' : text;
  }

  // Strict classification of ONE feed entry. Never throws for missing fields.
  function classifyBloggerEntry(entry) {
    var labels = getEntryLabels(entry);
    var reelsLabel = normalizeLabel(STUDIO_CONFIG.bloggerFeed.reelsLabel || 'Reels');
    var graphicsLabel = normalizeLabel(STUDIO_CONFIG.bloggerFeed.graphicsLabel || 'Graphics');
    // Accept both common Blogger labels: "Reel" and "Reels" (case/spacing normalized).
    // Keep this exact-label matching so unrelated labels cannot accidentally publish a Reel.
    var hasReels = labels.indexOf(reelsLabel) !== -1 ||
      labels.indexOf('reel') !== -1 ||
      labels.indexOf('reels') !== -1;
    var hasGraphics = labels.indexOf(graphicsLabel) !== -1;
    var title = decodeHtmlEntities(feedText(entry.title)).replace(/\s+/g, ' ').trim();
    var postUrl = getEntryPostUrl(entry);
    var publishedDate = Date.parse(feedText(entry.published) || feedText(entry.updated)) || 0;
    var info = { title: title, postUrl: postUrl, labels: labels };

    if (hasReels && hasGraphics) return { section: 'conflict', info: info };
    if (!hasReels && !hasGraphics) return { section: 'unlabeled', info: info };

    var contentHtml = feedText(entry.content);
    var summaryHtml = feedText(entry.summary);
    var mediaThumb = (entry['media$thumbnail'] && typeof entry['media$thumbnail'].url === 'string') ? entry['media$thumbnail'].url : '';
    var postId = getEntryPostId(entry);

    if (hasGraphics) {
      // Artwork priority: post body -> summary -> media$thumbnail (fallback only)
      var images = extractImagesFromContent(contentHtml);
      extractImagesFromContent(summaryHtml).forEach(function(img) {
        for (var i = 0; i < images.length; i++) { if (images[i].src === img.src) return; }
        images.push(img);
      });
      var imageSource = images.length ? 'post body' : '';
      if (!images.length && mediaThumb) {
        var thumb = safeHttpUrl(mediaThumb);
        if (thumb && !NON_ARTWORK_IMAGE_RE.test(thumb)) {
          var upgraded = upgradeBloggerImageUrl(thumb);
          images.push({ src: upgraded, fallback: upgraded !== thumb ? thumb : '' });
          imageSource = 'media$thumbnail';
        }
      }
      var sub = matchSublabel(labels, GRAPHICS_SUBLABELS);
      return {
        section: 'graphics',
        info: info,
        imageSource: imageSource,
        item: {
          id: 'gfx-' + postId,
          postKey: getEntryKey(entry),
          title: title,
          image: images.length ? images[0].src : '',
          imageFallback: images.length ? images[0].fallback : '',
          imageCount: images.length,
          category: sub ? sub.category : '',
          badge: sub ? sub.badge : 'GRAPHICS',
          categoryLabel: sub ? sub.label : 'Graphics',
          postUrl: postUrl,
          publishedDate: publishedDate
        }
      };
    }

    // Reels: a valid YouTube video ID is mandatory
    // Blogger may place the YouTube URL in an alternate link, media metadata, or another
    // serialized field rather than entry.content.$t. Inspect the full entry as a final fallback.
    var ytId = extractYouTubeIdFromPost(contentHtml, summaryHtml, mediaThumb);
    if (!ytId) {
      var entryText = '';
      try { entryText = JSON.stringify(entry); } catch (ignoreEntryJsonError) {}
      ytId = extractYouTubeIdFromText(entryText);
    }
    if (!ytId && postUrl) ytId = extractYouTubeIdFromText(postUrl);

    if (!ytId) return { section: 'reels-invalid', info: info };
    var reelSub = matchSublabel(labels, REELS_SUBLABELS);
    return {
      section: 'reels',
      info: info,
      item: {
        id: 'reel-' + postId,
        postKey: getEntryKey(entry),
        title: title,
        youtubeId: ytId,
        category: reelSub ? reelSub.category : '',
        badge: reelSub ? reelSub.badge : 'REEL',
        description: buildExcerpt(contentHtml || summaryHtml, title),
        postUrl: postUrl,
        publishedDate: publishedDate
      }
    };
  }

  function describePost(info) {
    return '"' + (info.title || '(untitled post)') + '"' + (info.postUrl ? ' <' + info.postUrl + '>' : '');
  }

  // Classify every collected entry. A malformed entry is skipped without affecting the others.
  function classifyBloggerEntries(entries) {
    var reels = [];
    var graphics = [];
    var notes = { reelsWithoutVideo: [], conflicts: [] };
    var stats = { total: entries.length, unlabeled: 0, malformed: 0, graphicsWithoutImage: 0, duplicateVideos: 0 };

    entries.forEach(function(entry) {
      var result;
      try {
        result = classifyBloggerEntry(entry);
      } catch (err) {
        stats.malformed++;
        feedLog('warn', 'Skipped a malformed post entry: ' + (err && err.message ? err.message : err));
        return;
      }
      if (result.section === 'graphics') {
        if (!result.item.image) {
          stats.graphicsWithoutImage++;
          feedLog('warn', "Graphics post " + describePost(result.info) + " has no usable artwork image (no <img> in the post body or summary, and no non-YouTube media$thumbnail). It is listed with a 'No artwork image' notice. Upload the artwork image into the post to display it.");
        } else if (result.imageSource === 'media$thumbnail') {
          feedLog('info', 'Graphics post ' + describePost(result.info) + ' has no image in the feed body (feed may be set to Short/jump-break); using its post thumbnail instead.');
        }
        if (!result.info.title) feedLog('warn', 'Graphics post at ' + (result.info.postUrl || '(unknown URL)') + ' has no title.');
        graphics.push(result.item);
      } else if (result.section === 'reels') {
        if (!result.info.title) feedLog('warn', 'Reels post at ' + (result.info.postUrl || '(unknown URL)') + ' has no title.');
        reels.push(result.item);
      } else if (result.section === 'reels-invalid') {
        notes.reelsWithoutVideo.push(result.info);
        feedLog('warn', "Reels post " + describePost(result.info) + " was skipped: no valid YouTube video link/embed was found (supported: youtube.com/watch?v=, youtu.be/, /shorts/, /embed/, /live/ or an embedded player).");
      } else if (result.section === 'conflict') {
        notes.conflicts.push(result.info);
        feedLog('warn', "Post " + describePost(result.info) + " has BOTH the 'Reels' and 'Graphics' labels, so it is shown in neither section. Edit the post in Blogger and keep only one of these two labels.");
      } else {
        stats.unlabeled++;
      }
    });

    function newestFirst(a, b) {
      return (b.publishedDate || 0) - (a.publishedDate || 0);
    }
    reels.sort(newestFirst);
    graphics.sort(newestFirst);

    // Two different Reels posts pointing at the same video would show the same Reel twice:
    // keep the newest one only.
    var seenVideos = {};
    reels = reels.filter(function(reel) {
      if (seenVideos[reel.youtubeId]) {
        stats.duplicateVideos++;
        feedLog('warn', 'Reels post "' + (reel.title || reel.postUrl) + '" uses the same YouTube video as a newer Reels post and was not shown twice.');
        return false;
      }
      seenVideos[reel.youtubeId] = true;
      return true;
    });

    return { reels: reels, graphics: graphics, notes: notes, stats: stats };
  }

  // Comprehensive Blogger feed discovery. Each run starts from a clean slate and replaces the
  // displayed data atomically, so retries and refreshes can never duplicate posts.
  var feedDiscoveryRunId = 0;
  var feedDiscoveryInFlight = false;

  function discoverBloggerPosts() {
    if (feedDiscoveryInFlight) return;
    feedDiscoveryInFlight = true;
    var runId = ++feedDiscoveryRunId;

    var cfg = STUDIO_CONFIG.bloggerFeed;
    var perPage = Math.min(150, Math.max(1, parseInt(cfg.maxResultsPerPage, 10) || 50));
    var maxTotal = Math.min(500, Math.max(1, parseInt(cfg.maxTotalPosts, 10) || 150));
    var maxPages = Math.ceil(maxTotal / perPage);

    bloggerFeedState.isLoading = true;
    bloggerFeedState.reelsError = false;
    bloggerFeedState.graphicsError = false;
    bloggerFeedState.reelsErrorMsg = '';
    bloggerFeedState.graphicsErrorMsg = '';
    renderReelsCarousel();
    renderGraphicsGrid();

    var endpoints = getBloggerFeedEndpoints();
    var attemptErrors = [];
    var collected = [];
    var seenKeys = {};
    var pagesFetched = 0;
    var partialError = null;

    if (!endpoints.length) {
      finish(new Error('the blog feed address could not be determined. Open this page from your website.'), null);
      return;
    }

    function tryEndpoint(index) {
      if (runId !== feedDiscoveryRunId) return;
      if (index >= endpoints.length) {
        finish(new Error(attemptErrors.join('; ')), null);
        return;
      }
      fetchPage(endpoints[index], 1, function(err) {
        attemptErrors.push(endpoints[index].name + ': ' + (err && err.message ? err.message : err));
        tryEndpoint(index + 1);
      }, index);
    }

    function fetchPage(endpoint, startIndex, onFirstPageError, endpointIndex) {
      requestFeedPage(endpoint, startIndex, perPage).then(function(data) {
        if (runId !== feedDiscoveryRunId) return;
        pagesFetched++;
        var feed = data.feed;
        // A valid empty Blogger feed simply has no "entry" key.
        var entries = feed.entry ? (Array.isArray(feed.entry) ? feed.entry : [feed.entry]) : [];
        // A same-origin route can return a valid but unrelated/empty feed on custom domains.
        // Try the next endpoint before declaring there are no published posts.
        if (startIndex === 1 && entries.length === 0 && typeof endpointIndex === 'number' && endpointIndex + 1 < endpoints.length) {
          feedLog('warn', 'Feed endpoint ' + endpoint.name + ' returned no posts; checking the next configured endpoint.');
          tryEndpoint(endpointIndex + 1);
          return;
        }
        var totalResults = parseInt(feedText(feed['openSearch$totalResults']), 10);
        var added = 0;
        entries.forEach(function(entry) {
          if (!entry || typeof entry !== 'object' || collected.length >= maxTotal) return;
          var key;
          try { key = getEntryKey(entry); } catch (e) { key = ''; }
          if (!key || seenKeys[key]) return;
          seenKeys[key] = true;
          collected.push(entry);
          added++;
        });
        var nextStart = startIndex + entries.length;
        var hasMore = entries.length >= perPage &&
          added > 0 &&
          collected.length < maxTotal &&
          pagesFetched < maxPages &&
          (isNaN(totalResults) || nextStart <= totalResults);
        if (hasMore) fetchPage(endpoint, nextStart, null, endpointIndex);
        else finish(null, endpoint, endpointIndex);
      }).catch(function(err) {
        if (runId !== feedDiscoveryRunId) return;
        if (startIndex === 1 && onFirstPageError) {
          onFirstPageError(err);
          return;
        }
        // A later page failed: keep everything already retrieved instead of discarding it.
        partialError = err;
        finish(null, endpoint);
      });
    }

    function finish(fatalError, endpoint, endpointIndex) {
      if (runId !== feedDiscoveryRunId) return;
      if (!fatalError && typeof endpointIndex === 'number' && endpointIndex + 1 < endpoints.length && collected.length) {
        var probe = classifyBloggerEntries(collected);
        if (!probe.reels.length && !probe.graphics.length) {
          feedLog('warn', 'Feed endpoint ' + endpoint.name + ' returned posts but none matched the Reels/Graphics labels; checking the next configured endpoint.');
          collected = [];
          seenKeys = {};
          pagesFetched = 0;
          partialError = null;
          tryEndpoint(endpointIndex + 1);
          return;
        }
      }
      feedDiscoveryInFlight = false;
      bloggerFeedState.isLoading = false;
      bloggerFeedState.hasLoadedOnce = true;

      if (fatalError) {
        feedLog('error', 'Could not load the Blogger feed: ' + fatalError.message);
        if (!bloggerFeedState.hasSucceededOnce) {
          var msg = 'Could not load published posts from the Blogger feed. Please check your connection and try again.';
          bloggerFeedState.reelsError = true;
          bloggerFeedState.graphicsError = true;
          bloggerFeedState.reelsErrorMsg = msg;
          bloggerFeedState.graphicsErrorMsg = msg;
        }
        // If an earlier run succeeded, keep showing its real posts.
        renderReelsCarousel();
        renderGraphicsGrid();
        return;
      }

      if (partialError) {
        feedLog('warn', 'A later feed page failed (' + (partialError.message || partialError) + '); showing the ' + collected.length + ' posts retrieved before the failure.');
      }

      var result = classifyBloggerEntries(collected);
      bloggerFeedState.hasSucceededOnce = true;
      bloggerFeedState.notes = result.notes;

      // Atomic replacement: never merged with previous runs, so nothing can be duplicated.
      REELS_DATA = result.reels;
      GRAPHICS_DATA = result.graphics;
      applyReelFilter();
      applyGraphicsFilter();
      activeReelIndex = 0;
      renderReelsCarousel();
      renderGraphicsGrid();

      feedLog('info', 'Loaded ' + collected.length + ' published post(s) via ' + (endpoint ? endpoint.name : 'feed') +
        ' in ' + pagesFetched + ' page(s). Reels: ' + REELS_DATA.length + ', Graphics: ' + GRAPHICS_DATA.length +
        ', skipped Reels without a valid video: ' + result.notes.reelsWithoutVideo.length +
        ', label conflicts: ' + result.notes.conflicts.length +
        ', posts without Reels/Graphics label: ' + result.stats.unlabeled +
        (result.stats.malformed ? ', malformed entries: ' + result.stats.malformed : '') + '.');
    }

    tryEndpoint(0);
  }

  // WhatsApp Quotation Request Form Handler
  function setupWhatsAppQuoteForm() {
    var form = document.getElementById('whatsappQuoteForm');
    if (!form) return;

    var nameInput = document.getElementById('quoteName');
    var serviceSelect = document.getElementById('quoteService');
    var reqsTextarea = document.getElementById('quoteRequirements');
    var submitBtn = document.getElementById('quoteSubmitBtn');
    var feedbackEl = document.getElementById('quoteStatusFeedback');

    var nameError = document.getElementById('quoteNameError');
    var serviceError = document.getElementById('quoteServiceError');
    var reqsError = document.getElementById('quoteRequirementsError');

    var isSubmitting = false;

    // Helper to clear errors
    function clearErrors() {
      if (nameError) nameError.classList.remove('visible');
      if (serviceError) serviceError.classList.remove('visible');
      if (reqsError) reqsError.classList.remove('visible');
      if (nameInput) nameInput.classList.remove('field-error');
      if (serviceSelect) serviceSelect.classList.remove('field-error');
      if (reqsTextarea) reqsTextarea.classList.remove('field-error');
      if (feedbackEl) {
        feedbackEl.className = 'quote-status-feedback';
        feedbackEl.textContent = '';
      }
    }

    // Real-time input listeners to clear field-level error when user starts typing/selecting
    if (nameInput) {
      nameInput.addEventListener('input', function() {
        if (nameInput.value.trim().length > 0) {
          nameInput.classList.remove('field-error');
          if (nameError) nameError.classList.remove('visible');
        }
      });
    }
    if (serviceSelect) {
      serviceSelect.addEventListener('change', function() {
        if (serviceSelect.value) {
          serviceSelect.classList.remove('field-error');
          if (serviceError) serviceError.classList.remove('visible');
        }
      });
    }
    if (reqsTextarea) {
      reqsTextarea.addEventListener('input', function() {
        if (reqsTextarea.value.trim().length > 0) {
          reqsTextarea.classList.remove('field-error');
          if (reqsError) reqsError.classList.remove('visible');
        }
      });
    }

    form.addEventListener('submit', function(e) {
      e.preventDefault();

      if (isSubmitting) return;

      clearErrors();

      var nameVal = (nameInput && nameInput.value) ? nameInput.value.trim() : '';
      var serviceVal = (serviceSelect && serviceSelect.value) ? serviceSelect.value.trim() : '';
      var reqsVal = (reqsTextarea && reqsTextarea.value) ? reqsTextarea.value.trim() : '';

      var firstInvalid = null;

      // Validate Name
      if (!nameVal) {
        if (nameInput) nameInput.classList.add('field-error');
        if (nameError) nameError.classList.add('visible');
        if (!firstInvalid) firstInvalid = nameInput;
      }

      // Validate Field / Service
      if (!serviceVal) {
        if (serviceSelect) serviceSelect.classList.add('field-error');
        if (serviceError) serviceError.classList.add('visible');
        if (!firstInvalid) firstInvalid = serviceSelect;
      }

      // Validate Detailed Requirements
      if (!reqsVal) {
        if (reqsTextarea) reqsTextarea.classList.add('field-error');
        if (reqsError) reqsError.classList.add('visible');
        if (!firstInvalid) firstInvalid = reqsTextarea;
      }

      // Focus first invalid element
      if (firstInvalid) {
        try {
          firstInvalid.focus();
        } catch (err) {}
        return;
      }

      // Prevent accidental rapid duplicate submissions
      isSubmitting = true;
      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.style.opacity = '0.75';
      }

      // Construct formatted WhatsApp message strictly matching specification
      var brandName = (STUDIO_CONFIG && STUDIO_CONFIG.brandName) ? STUDIO_CONFIG.brandName : 'Singh Creative Studio';
      var tagline = (STUDIO_CONFIG && STUDIO_CONFIG.tagline) ? STUDIO_CONFIG.tagline : 'Ideas Made Visible.';
      var waPhone = '919334603912';

      var message = '✨ NEW QUOTATION REQUEST\n' +
        '━━━━━━━━━━━━━━━━━━\n\n' +
        '👤 Client Name:\n' + nameVal + '\n\n' +
        '🎯 Service / Field:\n' + serviceVal + '\n\n' +
        '📝 Project Requirements:\n' + reqsVal + '\n\n' +
        '━━━━━━━━━━━━━━━━━━\n' +
        '📩 Source: ' + brandName + '\n' +
        '💡 Tagline: ' + tagline + '\n\n' +
        'Please review this request and share the next steps and quotation. Thank you!';

      var waUrl = 'https://wa.me/' + waPhone + '?text=' + encodeURIComponent(message);

      // Open WhatsApp safely in mobile and desktop
      try {
        var openedWin = window.open(waUrl, '_blank', 'noopener,noreferrer');
        if (!openedWin || openedWin.closed || typeof openedWin.closed === 'undefined') {
          // If popup is blocked, redirect window location safely
          window.location.href = waUrl;
        }

        if (feedbackEl) {
          feedbackEl.className = 'quote-status-feedback info';
          feedbackEl.textContent = 'Your quotation request is ready in WhatsApp. Review it and tap Send.';
        }
      } catch (openErr) {
        if (feedbackEl) {
          feedbackEl.className = 'quote-status-feedback error';
          feedbackEl.textContent = 'Could not open WhatsApp automatically. Please click the button again or contact us directly on WhatsApp at +' + waPhone + '.';
        }
      }

      // Re-enable button after a brief cooldown to allow retry if desired
      setTimeout(function() {
        isSubmitting = false;
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.style.opacity = '1';
        }
      }, 2500);
    });
  }

  // Initialize Reels, Graphics, and Contact Quotation Modules
  renderReelsCarousel();
  setupReelsControls();
  renderGraphicsGrid();
  setupGraphicsControls();
  setupWhatsAppQuoteForm();
  discoverBloggerPosts();

})();
//
